INSERT INTO `knowledge_chapter` (`id`, `course_id`, `parent_id`, `chapter_code`, `title`, `level`, `sort_order`, `description`, `summary`) VALUES
(192, 1, 0, '8', '第 8 章 内嵌类与 lambda 表达式', 1, 8, '本章围绕内嵌类（nested class）与 lambda 表达式两种语法概念展开：8.1 节给出内嵌类的概念、使用原因与分类，并分别介绍成员内部类、局部内部类、匿名内部类和静态内嵌类的定义形式、访问权限、同名成员隐藏、外嵌类 this 引用、实例创建语法以及编译后字节码文件的命名规则；8.2 节介绍 lambda 表达式的语法与省略规则、函数式接口与@FunctionalInterface 注解、lambda 表达式的作用域与对外部变量的引用限制、静态方法引用、实例方法引用和构造方法引用，以及 lambda 表达式与 ArrayList 的 forEach()、removeIf()方法和 Comparator 接口的联合使用；8.3 节为课程思政案例，用外嵌类与内部类的结构关系和功能关系类比党的民主集中制；章末附选择题、填空题、简答题、分析题和编程题。', '前面已经学习了面向对象编程的核心概念：类、继承、多态等。本章学习两种常用的语法概念：内嵌类(nested class)和 lambda 表达式。内嵌类是定义在另一个类的内部的类。内嵌类机制在设计相互合作的类时，有助于将相关类绑定在一起。lambda 表达式能创建在将来某个时间点执行的代码块，可用于精简代码。通过使用 lambda 表达式，可以用一种简洁的方式表示使用回调的代码。'),
(193, 1, 192, '8.1', '内嵌类', 2, 1, '内嵌类（nested class），是指定义在另一个类中的类。包含内嵌类的外部类被称为内部类的外嵌类。程序中使用内嵌类的原因主要有两个：一是内嵌类可以对同一包中的其它类隐藏，增强了代码的封装性。二是内嵌类方法可以访问定义该类的作用域中的属性和方法，包括作用域中的私有数据域。', NULL),
(194, 1, 193, '8.1.1', '成员内部类', 3, 1, NULL, NULL),
(195, 1, 193, '8.1.2', '局部内部类', 3, 2, NULL, NULL),
(196, 1, 193, '8.1.3', '匿名内部类', 3, 3, NULL, NULL),
(197, 1, 193, '8.1.4', '静态内嵌类', 3, 4, NULL, NULL),
(198, 1, 192, '8.2', 'lambda 表达式', 2, 2, 'lambda 表达式是 JAVA SE 8 提供的一种新特性，可以看做是一段可以传递的代码。在 Java 语言中，lambda 表达式还可以被称为闭包或匿名函数。lambda 表达式体现了函数式编程的思想：对行为进行抽象。', NULL),
(199, 1, 198, '8.2.1', 'lambda 表达式语法', 3, 1, NULL, NULL),
(200, 1, 198, '8.2.2', 'lambda 表达式作用域', 3, 2, NULL, NULL),
(201, 1, 198, '8.2.3', '方法引用', 3, 3, NULL, NULL),
(202, 1, 198, '8.2.4', 'lambda 表达式与 ArrayList', 3, 4, NULL, NULL),
(203, 1, 198, '8.2.5', 'Comparator 接口', 3, 5, NULL, NULL),
(204, 1, 192, '8.3', '课程思政案例', 2, 3, '对应章节：8.1 内部类', NULL);
