(173, 195, '局部内部类', NULL, 1, '局部内部类,方法作用域,局部变量,封装性', 'P.357-358', 1),
(174, 196, '匿名内部类', NULL, 1, '匿名内部类,父类型,抽象方法,$n.class', 'P.358-360', 1),
(175, 197, '静态内嵌类', NULL, 1, '静态内嵌类,static,外嵌类类名,实例成员', 'P.360-361', 1),
(176, 199, 'lambda 表达式语法', NULL, 1, '参数列表,箭头,方法体,函数式接口,省略规则', 'P.361-365', 1),
(177, 200, 'lambda 表达式作用域', NULL, 1, '嵌套块作用域,变量捕获,最终变量,事实最终变量', 'P.365-366', 1),
(178, 201, '方法引用', NULL, 1, '静态方法引用,实例方法引用,构造方法引用,::', 'P.366-371', 1),
(179, 202, 'lambda 表达式与 ArrayList', NULL, 1, 'forEach,removeIf,Consumer,Predicate', 371, 1),
(180, 203, 'Comparator 接口', NULL, 1, 'Comparator 接口,compare,Collections.sort,匿名内部类,lambda 表达式', 'P.372-374', 1),
(181, 204, '课程思政案例', NULL, 1, '民主集中制,外嵌类与内部类,整体与局部,组织原则', 'P.374-375', 1),
(182, 192, '习题', NULL, 1, '字节码文件命名,隐藏现象,lambda 表达式语法,方法引用,Comparator 排序', 'P.376-384', 1);
INSERT INTO `knowledge_concept` (`id`, `chapter_id`, `name`, `definition`, `difficulty`, `page`, `page_order`) VALUES
(478, 193, '内嵌类（nested class）', '内嵌类（nested class），是指定义在另一个类中的类。包含内嵌类的外部类被称为内部类的外嵌类。', 1, 353, 1),
(479, 193, '外嵌类', '包含内嵌类的外部类被称为内部类的外嵌类。', 1, 353, 2),
(480, 193, '程序中使用内嵌类的原因', '程序中使用内嵌类的原因主要有两个：一是内嵌类可以对同一包中的其它类隐藏，增强了代码的封装性。二是内嵌类方法可以访问定义该类的作用域中的属性和方法，包括作用域中的私有数据域。', 1, 353, 3),
(481, 193, '内部类（inner class）', '一个内部类是一个没有显式或隐式静态的内嵌类。内部类按照有无实名，可以分为：实名内部类、匿名内部类。而实名内部类包括成员内部类、局部内部类。', 1, 353, 4),
(482, 193, '隐式的静态内嵌类', '除了使用 static 关键字修饰的内嵌类，一些内嵌类隐式成为静态内嵌类。这些隐式的静态内嵌类包括：成员枚举类、局部枚举类、成员记录类、局部记录类、一个接口的成员类。', 1, 353, 5),
(483, 194, '成员内部类', '成员内部类是最普通的内部类，它的定义为位于另一个类的内部。', 1, 354, 1),
(484, 194, '成员内部类的访问权限修饰符', '成员内部类位于外嵌类的类体之中，内部类与外嵌类的其他成员一样，可以使用访问权限修饰符。访问权限修饰符修饰成员内部类产生的效果与修饰类的其他成员是一样的。', 1, 354, 2),
(485, 194, '实名内部类的字节码文件', '存在实名内部类的源代码在编译后，外嵌类和实名内部类都会产生自己独立的字节码文件。对于实名内部类，其字节码文件的文件名为：外嵌类名$实名内部类名.class。', 1, 354, 3),
(486, 194, '隐藏现象', '当成员内部类拥有和外嵌类同名的成员变量或者方法时，会发生隐藏现象。这时，在成员内部类中，默认访问的是成员内部类的成员。', 1, 354, 4),
(487, 194, '外嵌类名.this', '例如，如果程序清单 8-1 中成员内部类 Draw 也有一个名称为 radius 的成员变量，就会发生隐藏现象。这时，如果类 Draw 要访问外嵌类的私有成员变量 radius，就必须显式引用外嵌类的 radius，引用代码为：CircleNestDemo.this.radius。', 1, 355, 1),
(488, 194, '外嵌类实例名.new', '在创建成员内部类对象时，必须先创建一个外嵌类实例。在上面的创建语法中，赋值运算符右边需要使用外嵌类实例结合 new 运算符（外嵌类实例名.new）来创建内部类实例，内部类类名(参数列表)对应要调用的内部类构造方法。', 1, 355, 2),
(489, 194, '成员内部类的静态方法', '另外，成员内部类允许定义静态方法，在外嵌类的外部被引用时，需使用“外嵌类名.内部类名.静态方法”进行调用。', 1, 355, 3),
(490, 194, '外嵌类对成员内部类成员的访问', '虽然成员内部类可以访问外嵌类的所有成员，但是，反过来，外嵌类却不能直接访问成员内部类的成员。如果要在外嵌类中访问成员内部类的成员，必须先创建一个成员内部类的对象，再通过这个对象的引用来访问成员内部类的成员。', 1, 356, 1),
(491, 195, '局部内部类', '局部内部类是指定义在外嵌类的方法里面或者一个语句块作用域里面的类。局部内部类的访问权限仅限于方法内或者该语句块作用域内，而且，局部内部类与方法的局部变量一样，不能用 public、protected、private 以及 static、sealed 修饰符进行修饰。', 1, 357, 1),
(492, 195, '局部内部类的封装性', '因此，局部内部类对外部世界是完全隐藏的，体现了更好的封装性。', 1, 357, 2),
(493, 195, '局部内部类可访问的局部变量', '与成员内部类相比，局部内部类还有一个优势：局部内部类不仅能访问外嵌类的成员，还可以访问所在方法或所在语句块作用域内的局部变量。', 1, 358, 1),
(494, 196, '匿名内部类', '在使用局部内部类的场景中，如果局部内部类的名称只被使用一次，仅用于创建这个局部内部类的对象，那么可以对局部内部类进行简化，可以无需指定局部内部类的类名。这样的一个没有名字的局部内部类被称为匿名内部类。', 1, 358, 1),
(495, 196, '匿名内部类的父类型', '这里的父类型既可以是接口，如程序清单 8-5 的 Eatable，也可以是一个类（通常是抽象类）。当父类型是接口时，父类型构造方法参数列表为空，调用的构造方法是 Object()，语法形式可以简化为：', 1, 359, 1),
(496, 196, '匿名内部类没有构造方法', '一个匿名内部类没有类名，而构造方法的名称必须与类名相同，因此，匿名内部类没有构造方法定义。', 1, 360, 1),
(497, 196, '匿名内部类必须实现父类型的所有抽象方法', '一个匿名内部类必须实现父类型的所有抽象方法，因为匿名内部类自身不能是抽象的。', 1, 360, 2),
(498, 196, '匿名内部类的字节码文件', '每个匿名内部类都有自己对应的字节码文件，字节码文件命名形式是：外嵌类类名$n.class，在美元符号$后的符号 n 表示从 1 开始编号的整数。', 1, 360, 3),
(499, 197, '静态内嵌类', '用关键字 static 显式修饰的内嵌类是静态内嵌类，静态内嵌类没有对外嵌类对象的引用。', 1, 360, 1),
(500, 197, '静态内嵌类的访问限制', '静态内嵌类与成员内部类不同，不再持有外嵌类的引用，即不能使用“外嵌类名.this”引用外嵌类的实例成员。因此，静态内嵌类不能访问外嵌类的实例成员。静态内嵌类可以通过外嵌类的类名访问外嵌类的静态成员。', 1, 360, 2),
(501, 197, '隐式声明的静态内嵌类', '除了显式声明的静态内嵌类，隐式声明的静态内嵌类包括：成员枚举类、局部枚举类、成员记录类、局部记录类、一个接口的成员类。', 1, 360, 3),
(502, 197, '静态内嵌类中被隐藏的静态成员', '静态内部类的静态成员变量 k 隐藏外嵌类的静态成员 k，为了访问外嵌类的静态成员 k，可以使用外嵌类类名访问，如第 18 行“OutterCls.k”。当静态内部类访问外嵌类中未被隐藏的静态成员时，可以省略外嵌类类名，如第 18 行访问 m 的情况。', 1, 361, 1),
(503, 198, 'lambda 表达式', 'lambda 表达式是 JAVA SE 8 提供的一种新特性，可以看做是一段可以传递的代码。在 Java 语言中，lambda 表达式还可以被称为闭包或匿名函数。lambda 表达式体现了函数式编程的思想：对行为进行抽象。', 1, 361, 1),
(504, 198, 'lambda 表达式的直观好处', 'lambda 表达式一个直观的好处，就是可以简化匿名内部类的代码，使得程序员不再纠缠于匿名内部类的冗繁和可读性。', 1, 361, 2),
(505, 199, '参数列表', '参数列表是由圆括号括起来的零个或多个参数，多个参数之间使用逗号分隔，对应函数式接口中抽象方法的参数列表。', 1, 362, 1),
(506, 199, '箭头', '箭头是符号->，相当于一个分隔符。', 1, 362, 2),
(507, 199, '方法体', '方法体是花括号括起来的零条或多条语句组成，对应匿名内部类对抽象方法重写的方法体。', 1, 362, 3),
(508, 199, '函数式接口（Functional Interface）', '函数式接口是一个不能使用关键 seal 修饰、必须有且只有一个抽象方法（除了 Object 的 public 方法）的接口。', 1, 362, 4),
(509, 199, '@FunctionalInterface', '函数式接口可以使用注解@FunctionalInterface 进行修饰，其作用仅仅在于强迫 Java 编译器对接口进行语法检查，是否只定义了一个抽象方法，如果否，Java 编译器就会报错。', 1, 362, 5),
(510, 199, '单抽象方法（Single Abstract Method，SAM）接口', '因此，函数式接口也可以被成为单抽象方法（Single Abstract Method，SAM）接口。', 1, 362, 6),
(511, 199, '函数式接口的抽象方法限制', '函数式接口不仅要有一个抽象方法，而且该抽象方法不能是类 Object 的 public 方法', 1, 363, 1),
(512, 199, '函数式接口的子接口', '然而，接口 NonFunc 的子接口可以是函数式接口，只要这个子接口声明了一个不是类 Object 成员的抽象方法', 1, 363, 2),
(513, 199, 'lambda 表达式省略参数的数据类型', '(1) lambda 表达式参数列表中参数的数据类型可以省略，而且必须同时省略，不允许省略其中一部分参数的数据类型，而另一部分参数不省略。', 1, 365, 1),
(514, 199, 'lambda 表达式省略圆括号', '在 lambda 表达式省略参数的数据类型之后，如果参数列表只有一个参数时，圆括号可以省略。其他情况下，圆括号不能省略。', 1, 365, 2),
(515, 199, 'lambda 表达式省略花括号和分号', '当 lambda 表达式方法体中的语句只有一条时，可以省略花括号和分号。进一步，当这一条语句是 return 语句时，return 也必须省略。', 1, 365, 3),
(516, 199, 'Java 编译器处理 lambda 表达式的三个步骤', '通常，Java 编译器处理 lambda 表达式有三个步骤：①确定 lambda 表达式的数据类型；②确定参数的数据类型；③确定语句。', 1, 365, 4),
(517, 200, 'lambda 表达式的作用域', 'lambda 表达式的体与嵌套块具有相同的作用域。因此，在 lambda 表达式中声明一个与外部作用域同名的局部变量是不合法的。', 1, 365, 1),
(518, 200, 'lambda 表达式捕获外围作用域的变量', '因此，lambda 表达式可以捕获(或访问)外围作用域中变量的值。', 1, 365, 2),
(519, 200, 'lambda 表达式访问外围变量的限制', '然而，lambda 表达式访问外围方法或类中的变量，有一个重要的限制：只能引用外部变量的值而不能改变外部变量的值。并且，如果在 lambda 表达式中引用了一个外部变量，这个外部变量也不能在外部改变。', 1, 365, 3),
(520, 200, '事实最终（effective final）变量', '事实最终变量是指一个变量被初始化后就不再为其赋新值。', 1, 365, 4),
(521, 200, 'lambda 表达式引用的外部变量的具体限制', '因此，lambda 表达式中引用的外部变量是有具体限制的：一方面，lambda 表达式不能对引用的外部变量进行修改；另一方面，如果 lambda 表达式引用了一个外部变量，这个外部变量就成为事实最终变量，在外部作用域中，不允许对其进行修改。', 1, 366, 1),
(522, 201, '方法引用', '方法引用也称为函数引用，是指在 lambda 表达式中引用一个已经存在的方法，使其替代 lambda 表达式完成接口的实现。', 1, 366, 1),
(523, 201, '方法引用的使用场合', '引入 lambda 表达式主要是为了简化函数式接口的实现。因此，在 lambda 表达式中，不应该出现比较复杂的逻辑。如果 lambda 表达式的逻辑过于复杂，就会对程序的易读性造成不好的影响。', 1, 366, 2),
(524, 201, '方法引用的三种形式', '根据方法引用的方法类型，可以分为静态方法引用、实例方法引用、构造方法引用，下面对这三种引用形式分别进行介绍。', 1, 367, 1),
(525, 201, '静态方法引用', '静态方法引用，只需要静态方法名，不需要在方法名后加圆括号。', 1, 368, 1),
(526, 201, '被引用的静态方法的一致性', '被引用的静态方法的参数列表和返回值，与 lambda 表达式实现的接口中抽象方法的参数列表和返回值一致。被引用的静态方法的方法体，与 lambda 表达式的方法体一致。', 1, 368, 2),
(527, 201, '实例方法引用', '实例方法引用与静态方法不同，需要使用对象名，对象名可以是匿名的。', 1, 369, 1),
(528, 201, '构造方法引用', '第 4 行是 lambda 表达式的构造方法引用，由于对象 cstu1 的类型实现了接口 CreateStudent1，而接口 CreateStudent1 内部有一个带三个参数的抽象方法 create()，因此，这个构造方法引用表示引用的是 Student 类带三个参数的构造方法。', 1, 370, 1),
(529, 201, '方法引用的作用', '上述三种形式的方法引用，可以使代码简洁，提升程序的易读性。', 1, 371, 1),
(530, 202, 'forEach()方法', '该方法可对当前列表的每个元素执行给定的操作，直到处理完所有元素或该操作引发异常为止。如果指定了迭代顺序，则操作将按迭代顺序执行。操作引发的异常会中继到调用方。', 1, 371, 1),
(531, 202, 'removeIf()方法', '该方法删除当前列表中满足给定谓词（即某种条件）的所有元素。迭代期间或谓词引发的错误或运行时异常会中继到调用方。', 1, 371, 2),
(532, 202, 'ArrayList 中可使用 lambda 表达式的两个方法', 'ArrayList 中有两个方法可以使用 lambda 表达式，这两个方法是：forEach()、removeIf。', 1, 371, 3),
(533, 203, 'Comparator 接口', 'Java 语言提供的接口 java.util.Comparator<T>是一个函数式接口，它有一个抽象方法：', 1, 372, 1),
(534, 203, 'compare(T o1, T o2)方法', '该方法接受两个对象作为参数，并返回一个 int 值，表示它们的顺序。', 1, 372, 2),
(535, 203, 'Collections 类的静态方法 sort', '类 Collections 具有一个静态方法 sort，能够对列表对象进行排序', 1, 372, 3),
(536, 203, 'Collections.sort()的两个参数', '第一个参数是 List<T>，该类型是 ArrayList<E>的父类型，因此，Collections.sort()可以对 ArrayList 对象进行排序。第二个参数的类型 Comparator 接口类型，该接口是一个函数式接口，因此第二个参数可以用 lambda 表达式，也可以用匿名内部类对象。', 1, 372, 4),
(537, 203, '按自定义比较标准排序', '该示例能够按自定义比较标准，比较两个学生对象，结合方法 Collections.sort()得到学生列表按某一标准的升序或降序排列结果。', 1, 372, 5),
(538, 204, '民主集中制（课程思政案例）', '民主集中制是我们党的根本组织原则和领导制度，是马克思主义政党区别于其他政党的重要标志。', 1, 374, 1),
(539, 204, '外嵌类与内部类的类比设计', '针对上述思政教学目标，运用类比分析的方法，把共产党这个大组织机构类比为一个外嵌类，党的代表大会则是其中的一个内部类，运用外嵌类和内部类的结构关系和功能关系，讲授局部和整体，地方中央的关系', 1, 375, 1),
(540, 204, '外嵌类和内部类的结构关系', '首先，从外嵌类和内部类的结构关系看，内部类是嵌套于外嵌类的类之中。', 1, 375, 2),
(541, 204, '内部类的功能特征', '比如，内部类除了有自己的成员属性外，还可以访问操作外嵌类的所有成员属性。这一特征使得内部类可以控制更多的资源，实现更加强大的功能。', 1, 375, 3);
INSERT INTO `knowledge_code_snippet` (`id`, `chapter_id`, `title`, `code`, `is_key_example`, `page`, `page_order`) VALUES
(470, 194, '成员内部类定义的一般形式', '    [修饰符 1]class OuterClass { // 外嵌类\n       // ...\n       [修饰符 2] class NestedClass [extends…][implements…] { // 成员内部类\n          // ...\n       }\n    }', 0, 354, 1),
(471, 194, '程序清单 8-1　CircleNestDemo.java', '1  public class CircleNestDemo { //外嵌类\n2     private double radius = 0;\n3     public static int count =1;\n4     public CircleNestDemo(double radius) {\n5        this.radius = radius;\n6     }\n7     //内部类的定义\n8     class Draw {\n9        public void drawSahpe() {\n10          System.out.println(radius); //访问外嵌类的 private 成员\n11          System.out.println(count); //访问外嵌类的静态成员\n12       }\n13    }\n14 }', 0, 354, 2),
(472, 194, '成员内部类中访问外嵌类同名成员的语法形式', '外嵌类名.this.成员变量\n外嵌类名.this.成员方法', 0, 354, 3),
(473, 194, '创建成员内部类实例的一般语法形式', '外嵌类类名.内部类类名 内部类对象名 = 外嵌类实例名.new 内部类类名(参数列表);', 0, 355, 4),
(474, 194, '程序清单 8-2　InnerClassDemo1.java', '1  public class InnerClassDemo1 {\n2     public static void main(String[] args) {\n3        OutterCls1 outter = new OutterCls1();\n4        //外嵌类作用域之外创建一个内部类实例\n5        OutterCls1.InnerCls1 inner = outter.new InnerCls1();\n6        System.out.println(inner.toString());\n7        System.out.println("内部类对象的数量：" +\n8                 OutterCls1.InnerCls1.getCount());\n9     }\n10 }\n11 //外嵌类 OutterCls1 的定义\n12 class OutterCls1{\n13    int i = 10;\n14    public OutterCls1() {\n15       System.out.println("外嵌类创建");\n16    }\n17    //成员内部类定义\n18    class InnerCls1{\n19       int i = 1;\n20       static int count = 0;\n21       public InnerCls1() {\n22          System.out.println("内部类创建");\n23       }\n24       @Override\n25       public String toString() {\n26          return "实名内部类对象:i=" + i +\n27             "\\n 外嵌类对象:i=" + getOutterI();\n28       }\n29       //访问外嵌类被隐藏的同名成员变量 i\n30       public int getOutterI() {\n31          return OutterCls1.this.i;\n32       }\n33       //内部类静态方法的定义\n34       public static int getCount() {\n35          return count;\n36       }\n37    }\n38 }', 0, 355, 5),
(475, 194, '程序清单 8-2 运行结果', '外嵌类创建\n内部类创建\n实名内部类对象:i=1\n外嵌类对象:i=10\n内部类对象的数量：1', 0, 356, 6),
(476, 194, '程序清单 8-3　CircleNestDemo2.java', '1  package chapt8;\n2  public class CircleNestDemo2 {\n3     private double radius = 0;\n4     public CircleNestDemo2() {\n5        Draw dr=getDrawInstance();\n6        //color = "BLUE"; //错误，不能直接访问\n7        System.out.println(dr.drawShape());//调用内部类的成员方法\n8     }\n9     public CircleNestDemo2(double radius) {\n10       this.radius = radius;\n11       Draw dr=getDrawInstance();\n12       dr.color = "GREEN";//访问内部类的成员变量\n13       System.out.println(dr.drawShape());\n14    }\n15    @Override\n16    public String toString() {\n17       return this.getClass().toString();\n18    }\n19    //创建一个内部类对象\n20    private Draw getDrawInstance() {\n21       return new Draw();\n22    }\n23    class Draw { //内部类\n24       String color = "RED";\n25       public String drawShape () {\n26          return "半径："+ radius\n27                +"；颜色："+ color; //外嵌类的 private 成员\n28       }\n29    }\n30    public static void main(String[] args) {\n31       CircleNestDemo2 c1 = new CircleNestDemo2();\n32       System.out.println(c1);\n33       CircleNestDemo2 c2 = new CircleNestDemo2(5);\n34       System.out.println(c2);\n35    }\n36 }', 0, 356, 7),
(477, 194, '程序清单 8-3 运行结果', '半径：0.0；颜色：RED\nclass chapt8.CircleNestDemo2\n半径：5.0；颜色：GREEN\nclass chapt8.CircleNestDemo2', 0, 357, 8),
(478, 195, '程序清单 8-4　LocalInnerClassDemo.java', '1  public class LocalInnerClassDemo {\n2     public static String info(Eatable a) {\n3        return a.howToEat();\n4     }\n5     public static void eatFruit() {\n6        String eatInfo = "水果的吃法";\n7        //局部内部类定义，class 关键字不允许加访问修饰符和 static 关键字\n8        class Apple implements Eatable{\n9           @Override\n10          public String howToEat() {\n11             return eatInfo + "：榨苹果汁";\n12          }\n13       }\n14       var apple = new Apple();\n15       System.out.println(info(apple));\n16    }\n17    public static void main(String[] args) {\n18       eatFruit();\n19    }\n20 }\n21 interface Eatable{\n22    String howToEat();\n23 }', 0, 358, 9),
(479, 195, '程序清单 8-4 运行结果', '水果的吃法：榨苹果汁', 0, 358, 10),
(480, 196, '程序清单 8-5　AnnonymousInnerClassDemo.java', '1  public class AnnonymousInnerClassDemo {\n2     public static String info(Eatable a) {\n3        return a.howToEat();\n4     }\n5     public static void eatFruit() {\n6        String eatInfo = "水果的吃法";\n7        var apple = new Eatable() {//匿名内部类定义\n8           @Override\n9           public String howToEat() {\n10             return eatInfo + "：榨苹果汁";\n11          }\n12       };\n13       System.out.println(info(apple));\n14    }\n15    public static void main(String[] args) {\n16       eatFruit();\n17    }\n18 }', 0, 359, 11),
(481, 196, '程序清单 8-5 运行结果', '// 图 8-2a　局部内部类\nclass Apple implements Eatable{\n   @Override\n   public String howToEat() {\n      return eatInfo + "：榨苹果汁";\n   }\n}\nvar apple = new Apple();\n\n// 图 8-2b　匿名内部类\nvar apple = new Eatable() {//匿名内部类定义\n   @Override\n   public String howToEat() {\n      return eatInfo + "：榨苹果汁";\n   }\n};', 0, 359, 12),
(482, 196, '匿名内部类的语法形式', 'new 父类型名称(父类型构造方法参数列表){\n      匿名内部类的成员方法和成员数据域定义;\n}', 0, 359, 13),
(483, 196, '父类型为接口时匿名内部类的简化语法形式', 'new 接口名(){\n      数据域定义；\n      方法定义；\n}', 0, 359, 14),
(484, 197, '显式声明静态内嵌类的一般形式', '[修饰符 1]class OuterClass {         // 外嵌类\n   // ...\n   [修饰符 2] static class NestedClass { // 静态内嵌类\n      // ...\n   }\n}', 0, 360, 15),
(485, 197, '静态内嵌类对象的创建语法形式', '外嵌类名.静态内嵌类 内部类对象名 = new 外嵌类名.静态内嵌类();', 0, 360, 16),
(486, 197, '程序清单 8-6　StaticNestedClsDemo.Java', '1  public class StaticNestedClsDemo {\n2     public static void main(String[] args) {\n3        //静态内嵌类对象的创建\n4        OutterCls.StaticInner inner = new OutterCls.StaticInner();\n5        inner.show();\n6     }\n7  }\n8  class OutterCls{\n9     int i = 2;\n10    static int k = 3;\n11    static int m = 4;\n12    static class StaticInner{\n13       int i = 5;\n14       static int j = 6;\n15       static int k = 7;\n16       public void show() {\n17          System.out.printf("i=%d,j=%d,k=%d\\n",i,j,k);\n18          System.out.printf("外嵌类:k=%d,m=%d\\n",OutterCls.k,m);\n19       }\n20    }\n21 }', 0, 360, 17),
(487, 197, '程序清单 8-6 运行结果', 'i=5,j=6,k=7\n外嵌类:k=3,m=4', 0, 361, 18),
(488, 199, '程序清单 8-7　LambdaDemo1.java', '1  public class LambdaDemo1 {\n2     public static String info(EatMethod a) {\n3        return a.howToEat();\n4     }\n5     public static void eatFruit() {\n6        String eatInfo = "水果的吃法";\n7        //下面赋值语句右边是 Lambda 表达式\n8        EatMethod apple = () -> { return eatInfo + "：榨苹果汁"; };\n9        System.out.println(info(apple));\n10    }\n11    public static void main(String[] args) {\n12       eatFruit();\n13    }\n14 }\n15 //函数式接口定义\n16 @FunctionalInterface\n17 interface EatMethod{\n18    String howToEat();\n19 }', 0, 361, 19),
(489, 199, '图 8-3 lambda 表达式替换匿名内部类', 'EatMethod apple = () -> { return eatInfo + "：榨苹果汁"; };\n\nvar apple = new Eatable() {//匿名内部类定义\n      @Override\n      public String howToEat() {\n         return eatInfo + "：榨苹果汁";\n      }\n};', 0, 362, 20),
(490, 199, 'lambda 表达式的一般语法形式', '(数据类型 参数名称) ->{ 语句组 }', 0, 362, 21),
(491, 199, '省略花括号和 return 后的 lambda 表达式', 'EatMethod apple = () -> eatInfo + "：榨苹果汁";', 0, 363, 22),
(492, 199, 'lambda 表达式直接作为方法实参', 'System.out.println(info(() -> eatInfo + "：榨苹果汁"));', 0, 363, 23),
(493, 199, '接口 NonFunc：抽象方法是类 Object 的 public 方法', 'interface NonFunc {\n      boolean equals(Object obj);\n}', 0, 363, 24),
(494, 199, '接口 Func：NonFunc 的函数式子接口', 'interface Func extends NonFunc {\n      int compare(String o1, String o2);\n}', 0, 363, 25),
(495, 199, 'java.util.Comparator<T> 的接口定义', 'interface Comparator<T> {\n      boolean equals(Object obj); //类 Object 的 public 方法\n      int compare(T o1, T o2); //不是类 Object 的 public 方法\n}', 0, 363, 26),
(496, 199, '具有混淆性的接口 Func 定义', 'interface Func {\n      int m();\n      Object clone();\n}', 0, 363, 27),
(497, 199, '程序清单 8-8　LambdaDemo2.java', '1  import java.util.Arrays;\n2  public class LambdaDemo2 {\n3     public static void printMin(Min m, int[] a) {\n4        Arrays.sort(a);\n5        m.handle(a[0]);\n6     }\n7     public static void printMaxMin(MaxMin m, int[] a) {\n8        Arrays.sort(a);\n9        m.handle(a[0], a[a.length - 1]);\n10    }\n11    public static void main(String[] args) {\n12       int[] a = {5, 2, 7, 9, 12};\n13       //一个参数的完整形式\n14       printMin((int min) ->{System.out.println("最小值："+min);}, a);\n15       //各种省略模式\n16       printMin((min) ->{System.out.println("最小值："+min);}, a);\n17       printMin( min ->{System.out.println("最小值："+min);}, a);\n18       printMin( min ->System.out.println("最小值："+min) , a);\n19       //两个参数的情况\n20       printMaxMin((int max,int min)->{System.out.println(max+":"+min);},a);\n21       printMaxMin((max,min)->System.out.println(max+":"+min),a);\n22    }\n23 }\n24 @FunctionalInterface\n25 interface Min{\n26    void handle(int min);\n27 }\n28 @FunctionalInterface\n29 interface MaxMin{\n30    void handle(int max, int min);\n31 }', 0, 364, 28),
(498, 199, '程序清单 8-8 运行结果', '最小值：2\n最小值：2\n最小值：2\n最小值：2\n2:12\n2:12', 0, 364, 29),
(499, 199, '一个参数的 lambda 表达式的等价赋值形式', 'Min min = (int min) ->{System.out.println("最小值："+min);}\nprintMin(min, a);', 0, 365, 30),
(500, 199, '省略数据类型与花括号的 lambda 表达式', 'printMin(min ->System.out.println("最小值："+min), a);', 0, 365, 31),
(501, 200, 'lambda 表达式捕获外部变量 eatInfo', 'EatMethod apple = () -> { return eatInfo + "：榨苹果汁"; };', 0, 365, 32),
(502, 200, '程序清单 8-9　LambdaDemo3.java', '1  public class LambdaDemo3 {\n2     public static void printMax(Max max,int[] a) {\n3        max.handle(a);\n4     }\n5     public static void main(String[] args) {\n6        int[] a = {5, 2, 7, 9, 12};\n7        int count = a.length;\n8        int i = 1;\n9        int j =0;\n10       printMax(e->{\n11       //i++; //错误，必须是常量或事实最终变量\n12       //int j = 1; //错误，在外部作用域已经定义了变量 j\n13       Arrays.sort(a);\n14       System.out.println("max:"+a[count-1]);\n15       }, a);\n16       //count--;//错误，count 是一个事实最终变量\n17    }\n18 }\n19 @FunctionalInterface\n20 interface Max{\n21    void handle(int[] a);\n22 }', 0, 366, 33),
(503, 200, '程序清单 8-9 运行结果', 'max:12', 0, 366, 34),
(504, 201, '静态方法引用的一般语法形式', '类名::静态方法名', 0, 367, 35),
(505, 201, '程序清单 8-10　ReferStaticMethod', '1  public class ReferStaticMethod {\n2     public static void main(String[] args) {\n3        Scanner input = new Scanner(System.in);\n4        System.out.print("请输入两个浮点数：");\n5        double a = input.nextDouble();\n6        double b = input.nextDouble();\n7        //lambda 表达式静态方法引用实现接口\n8        SubInterface1 subObj1 = Calculator::subtraction;\n9        //lambda 表达式原始形式实现接口\n10       SubInterface1 subObj2 = (e1, e2) -> {\n11          if(e1 > e2)\n12             return e1 - e2;\n13          else\n14             return e2 - e1;\n15          };\n16       System.out.println("静态方法引用：" + subObj1.handle(a, b));\n17       System.out.println("原始形式：" + subObj2.handle(a, b));\n18    }\n19 }\n20 class Calculator{\n21    public static double subtraction(double a, double b) {\n22       if(a > b)\n23          return a - b;\n24       else\n25          return b - a;\n26    }\n27 }\n28 @FunctionalInterface\n29 interface SubInterface1{\n30    double handle(double d1, double d2);\n31 }', 0, 367, 36),
(506, 201, '程序清单 8-10 运行结果', '请输入两个浮点数：3.5 12.7\n静态方法引用：9.2\n原始形式：9.2', 0, 367, 37),
(507, 201, '实例方法引用的一般语法形式', '对象名::实例方法名', 0, 368, 38),
(508, 201, '程序清单 8-11　ReferInstanceMethod.java', '1  public class ReferInstanceMethod {\n2     public static void main(String[] args) {\n3        Scanner input = new Scanner(System.in);\n4        System.out.print("请输入两个浮点数：");\n5        double a = input.nextDouble();\n6        double b = input.nextDouble();\n7        //lambda 表达式实例方法引用实现接口，使用了匿名对象\n8        SubInterface2 subObj1 = new Calculator()::subtraction;\n9        //lambda 表达式原始形式实现接口\n10       SubInterface2 subObj2 = (e1, e2) -> {\n11          if(e1 > e2)\n12             return e1 - e2;\n13          else\n14             return e2 - e1;\n15          };\n16       System.out.println("实例方法引用：" + subObj1.handle(a, b));\n17       System.out.println("原始形式：" + subObj2.handle(a, b));\n18    }\n19    private static class Calculator{//静态内嵌类\n20       public double subtraction(double a, double b) {\n21          if(a > b)\n22             return a - b;\n23          else\n24             return b - a;\n25       }\n26    }\n27 }\n28 @FunctionalInterface\n29 interface SubInterface2{\n30    double handle(double d1, double d2);\n31 }', 0, 368, 39),
(509, 201, '程序清单 8-11 运行结果', '请输入两个浮点数：9.4 3.5\n实例方法引用：5.9\n原始形式：5.9', 0, 369, 40),
(510, 201, '构造方法引用的一般语法形式', '类名::new', 0, 369, 41),
(511, 201, '程序清单 8-12　ReferConstructor.java', '1  public class ReferConstructor {\n2     public static void main(String[] args) {\n3        //lambda 表达式构造方法引用实现接口 CreateStudent1\n4        CreateStudent1 cstu1 = Student::new;\n5        //lambda 表达式原始形式实现接口 CreateStudent1\n6        CreateStudent1 cstu2 = (e1, e2, e3) -> new Student(e1, e2, e3);\n7        //通过接口创建对象\n8        Student stu1 = cstu1.create("202305001", "刘策", 18);\n9        Student stu2 = cstu2.create("202305001", "张宇", 20);\n10       //lambda 表达式构造方法引用实现接口 CreateStudent2\n11       CreateStudent2 cstu3 = Student::new;\n12       //lambda 表达式原始形式实现接口 CreateStudent2\n13       CreateStudent2 cstu4 = () -> new Student();\n14       //通过接口创建对象\n15       Student stu3 = cstu3.create();\n16       Student stu4 = cstu4.create();\n17    }\n18 }\n19 class Student{\n20    String ID = "000000000";         //学号\n21    String name;                     //姓名\n22    int age;                         //年龄\n23    public Student(String iD, String name, int age) {\n24       ID = iD;\n25       this.name = name;\n26       this.age = age;\n27       System.out.println("创建学生对象信息如下：\\n"+ toString());\n28    }\n29    public Student() {\n30       System.out.println("创建学生对象默认信息：\\n" + toString());\n31    }\n32    @Override\n33    public String toString() {\n34       return "Student [ID=" + ID + ", name=" + name + ", age=" + age + "]";\n35    }\n36 }\n37 @FunctionalInterface\n38 interface CreateStudent1{\n39    Student create(String 学号, String 姓名, int 年龄);\n40 }\n41 @FunctionalInterface\n42 interface CreateStudent2{\n43    Student create();\n44 }', 0, 369, 42),
(512, 201, '程序清单 8-12 运行结果', '创建学生对象信息如下：\nStudent [ID=202305001, name=刘策, age=18]\n创建学生对象信息如下：\nStudent [ID=202305001, name=张宇, age=20]\n创建学生对象默认信息：\nStudent [ID=000000000, name=null, age=0]\n创建学生对象默认信息：\nStudent [ID=000000000, name=null, age=0]', 0, 370, 43),
(513, 202, 'ArrayList 的 forEach()方法声明', '(1) public void forEach(Consumer<? super E> action)', 0, 371, 44),
(514, 202, 'ArrayList 的 removeIf()方法声明', '(2) public boolean removeIf(Predicate<? super E> filter)', 0, 371, 45),
(515, 202, '程序清单 8-13　ListWithLambda.java', '1  public class ListWithLambda {\n2     public static void main(String[] args) {\n3        Integer[] intArray = {3, 5, 6, 2, 4, 7, 12};\n4        ArrayList<Integer> intList = new ArrayList<>(Arrays.asList(intArray));\n5        //方法引用\n6        intList.forEach(System.out::print);\n7        System.out.println("\\nlambda 表达式原始形式：");\n8        intList.forEach(e -> System.out.print(e + " "));\n9        System.out.println("\\n 打印偶数：");\n10       intList.forEach(e -> {\n11          if(e%2 == 0) {\n12             System.out.print(e + " ");\n13          }\n14       });\n15       //删除列表中偶数\n16       intList.removeIf(e -> e%2 == 0);\n17       System.out.println("\\n 删除偶数后：");\n18       intList.forEach(e -> System.out.print(e + " "));\n19    }\n20 }', 0, 371, 46),
(516, 202, '程序清单 8-13 运行结果', '35624712\nlambda 表达式原始形式：\n3 5 6 2 4 7 12\n打印偶数：\n6 2 4 12\n删除偶数后：\n357', 0, 371, 47),
(517, 203, 'Comparator 接口的抽象方法 compare()', 'public abstract int compare(T o1, T o2);', 0, 372, 48),
(518, 203, 'Collections 类的静态方法 sort()声明', 'public static <T> void sort(List<T> list, Comparator<? super T> c)', 0, 372, 49),
(519, 203, '程序清单 8-14　LambdaComparatorDemo.java', '1  public class LambdaComparatorDemo {\n2     public static void main(String[] args) {\n3        Pupils[] pArray = {\n4           new Pupils("50103","关一",12,1.45),\n5           new Pupils("40103","张二",11,1.43),\n6           new Pupils("40105","赵三",13,1.63),\n7           new Pupils("50109","李四",10,1.35),\n8           new Pupils("60103","黄羽",9,1.41),\n9        };\n10       //由学生数组创建列表\n11       ArrayList<Pupils> list = new ArrayList<>(Arrays.asList(pArray));\n12       //按学号升序排列\n13       System.out.println("按学号升序排列：");\n14       Collections.sort(list, new Comparator<Pupils>(){\n15          public int compare(Pupils o1, Pupils o2) {\n16             if(o1.ID.compareTo(o2.ID) > 0)\n17                return 1;\n18             else if(o1.ID == o2.ID)\n19                return 0;\n20             else return -1;\n21          }\n22       });\n23       list.forEach(e->System.out.print(e.ID + ":" + e.name + ";"));\n24       //按学号降序排列,lambda 表达式原始形式\n25       System.out.println("\\n 按学号降序升序排列：");\n26       Collections.sort(list, (o1, o2) -> {\n27          if(o1.ID.compareTo(o2.ID) < 0)\n28             return 1;\n29          else if(o1.ID == o2.ID)\n30             return 0;\n31          else return -1;\n32       });\n33       list.forEach(e->System.out.print(e.ID + ":" + e.name + ";"));\n34       //lambda 表达式静态方法引用\n35       System.out.println("\\n 按身高升序排列：");\n36       Collections.sort(list, HeightAscComparator::cmp);\n37       list.forEach(e->System.out.print(e.name +":"+ e.height +";"));\n38       //lambda 表达式实例方法引用\n39       System.out.println("\\n 按身高降序排列：");\n40       Collections.sort(list, new HeightDecComparator()::cmp);\n41       list.forEach(e->System.out.print(e.name +":"+ e.height +";"));\n42    }\n43    //按身高升序比较器\n44    private static class HeightAscComparator{\n45       static int cmp(Pupils o1, Pupils o2) {\n46          if(o1.height > o2.height)\n47             return 1;\n48          else if(o1.height == o2.height)\n49             return 0;\n50          else return -1;\n51       }\n52    }\n53    //按身高降序比较器\n54    private static class HeightDecComparator{\n55       int cmp(Pupils o1, Pupils o2) {\n56          if(o1.height < o2.height)\n57             return 1;\n58          else if(o1.height == o2.height)\n59             return 0;\n60          else return -1;\n61       }\n62    }\n63 }\n64 class Pupils{\n65    String ID = "00000"; //学号\n66    String name;                 //姓名\n67    int age;                     //年龄\n68    double height;               //身高\n69    public Pupils(String iD, String name, int age, double height) {\n70       ID = iD;\n71       this.name = name;\n72       this.age = age;\n73       this.height = height;\n74    }\n75    public Pupils() { }\n76 }\n77 }', 0, 372, 50),
(520, 203, '程序清单 8-14 运行结果', '学号升序排列：\n40103:张二;40105:赵三;50103:关一;50109:李四;60103:黄羽;\n按学号降序升序排列：\n60103:黄羽;50109:李四;50103:关一;40105:赵三;40103:张二;\n按身高升序排列：\n李四:1.35;黄羽:1.41;张二:1.43;关一:1.45;赵三:1.63;\n按身高降序排列：\n赵三:1.63;关一:1.45;张二:1.43;黄羽:1.41;李四:1.35;', 0, 374, 51);
INSERT INTO `knowledge_content` (`id`, `chapter_id`, `knowledge_point_id`, `content_type`, `content`, `page`, `page_order`) VALUES
(1739, 192, NULL, 1, '(1) 理解内嵌类概念', 353, 1),
(1740, 192, NULL, 1, '(2) 掌握成员内部类的定义和使用', 353, 2),
(1741, 192, NULL, 1, '(3) 掌握局部内部类的定义和使用', 353, 3),
(1742, 192, NULL, 1, '(4) 掌握匿名内部类的定义和使用', 353, 4),
(1743, 192, NULL, 1, '(5) 掌握静态内嵌类的定义和使用', 353, 5),
(1744, 192, NULL, 1, '(6) 掌握 lambda 表达式的语法，理解并能定义函数式接口', 353, 6),
(1745, 192, NULL, 1, '(7) 理解 lambda 表达式的作用域，掌握 lambda 表达式如何访问外部变量', 353, 7),
(1746, 192, NULL, 1, '(8) 掌握 lambda 表达式静态方法引用、实例方法引用、构造方法引用', 353, 8),
(1747, 192, NULL, 1, '(9) 掌握 ArrayList 的方法 forEach()、removeIf()与 lambda 表达式的联合使用', 353, 9),
(1748, 192, NULL, 1, '(10) 掌握 Comparator 接口的使用', 353, 10),
(1749, 192, NULL, 1, '前面已经学习了面向对象编程的核心概念：类、继承、多态等。本章学习两种常用的语法概念：内嵌类(nested class)和 lambda 表达式。内嵌类是定义在另一个类的内部的类。内嵌类机制在设计相互合作的类时，有助于将相关类绑定在一起。lambda 表达式能创建在将来某个时间点执行的代码块，可用于精简代码。通过使用 lambda 表达式，可以用一种简洁的方式表示使用回调的代码。', 353, 11),
(1750, 193, NULL, 1, '内嵌类（nested class），是指定义在另一个类中的类。包含内嵌类的外部类被称为内部类的外嵌类。程序中使用内嵌类的原因主要有两个：一是内嵌类可以对同一包中的其它类隐藏，增强了代码的封装性。二是内嵌类方法可以访问定义该类的作用域中的属性和方法，包括作用域中的私有数据域。', 353, 12),
(1751, 193, NULL, 1, '内嵌类可分为内部类（inner class）和静态内嵌类（static nest class），如图 8-1 所示。一个内部类是一个没有显式或隐式静态的内嵌类。内部类按照有无实名，可以分为：实名内部类、匿名内部类。而实名内部类包括成员内部类、局部内部类。除了使用 static 关键字修饰的内嵌类，一些内嵌类隐式成为静态内嵌类。这些隐式的静态内嵌类包括：成员枚举类、局部枚举类、成员记录类、局部记录类、一个接口的成员类。（图 8-1　内嵌类分类：图为层次分类图，内嵌类分为内部类和静态内嵌类两支，内部类按有无实名再分为实名内部类和匿名内部类两支，实名内部类又分为成员内部类和局部内部类两支）', 353, 13),
(1752, 193, NULL, 1, '下面从成员内部类、局部内部类、匿名内部类、静态内嵌类等几个方面展开介绍。', 354, 1),
(1753, 194, 172, 1, '成员内部类是最普通的内部类，它的定义为位于另一个类的内部。Java 语言定义成员内部类一般形式如下：', 354, 2),
(1754, 194, 172, 1, '修饰符 1 可以使用 public 或缺省（无修饰符），修饰符 2 可以是 public、protected、privated 或缺省。成员内部类位于外嵌类的类体之中，内部类与外嵌类的其他成员一样，可以使用访问权限修饰符。访问权限修饰符修饰成员内部类产生的效果与修饰类的其他成员是一样的。例如，如果一个内部类被修饰为 private，那么在外嵌类的作用域之外，该内部类是不能被访问的。如果一个内部类被修饰为 public，那么在外嵌类的作用域之外，该内部类也可以被访问，具体访问范围取决于外嵌类的访问权限。成员内部类也可以继承父类、实现接口。', 354, 3),
(1755, 194, 172, 1, '存在实名内部类的源代码在编译后，外嵌类和实名内部类都会产生自己独立的字节码文件。对于实名内部类，其字节码文件的文件名为：外嵌类名$实名内部类名.class。', 354, 4),
(1756, 194, 172, 1, '程序清单 8-1 给出一个成员内部类的简单示例。', 354, 5),
(1757, 194, 172, 1, '类 Draw 定义在类 CircleNestDemo 的内部，可以看做是类 CircleNestDemo 的一个成员，如程序清单 8-1 第 8 行-第 13 行所示。在这里，类 Draw 被称为成员内部类，类 CircleNestDemo 被称为外嵌类。成员内部类可以访问外嵌类的所有数据域和成员方法（包括 private 成员和静态成员）。例如，程序清单 8-1 第 10 行访问了外嵌类 CircleNestDemo 的私有成员变量 radius，第 11 行访问了外嵌类 CircleNestDemo 的公有静态成员 count。', 354, 6),
(1758, 194, 172, 1, '程序清单 8-1 对应的 Java 源文件只有一个：CircleNestDemo.java，产生的字节码文件有两个：CircleNestDemo.class，CircleNestDemo$Draw.class。', 354, 7),
(1759, 194, 172, 1, '需要注意的是，当成员内部类拥有和外嵌类同名的成员变量或者方法时，会发生隐藏现象。这时，在成员内部类中，默认访问的是成员内部类的成员。如果要在成员内部类中访问外嵌类的同名成员，需要以下面的形式进行访问：', 354, 8),
(1760, 194, 172, 1, '例如，如果程序清单 8-1 中成员内部类 Draw 也有一个名称为 radius 的成员变量，就会发生隐藏现象。这时，如果类 Draw 要访问外嵌类的私有成员变量 radius，就必须显式引用外嵌类的 radius，引用代码为：CircleNestDemo.this.radius。', 355, 1),
(1761, 194, 172, 1, '下面介绍成员内部类的实例创建方法，创建成员内部类实例的一般语法形式如下：', 355, 2),
(1762, 194, 172, 1, '在创建成员内部类对象时，必须先创建一个外嵌类实例。在上面的创建语法中，赋值运算符右边需要使用外嵌类实例结合 new 运算符（外嵌类实例名.new）来创建内部类实例，内部类类名(参数列表)对应要调用的内部类构造方法。', 355, 3),
(1763, 194, 172, 1, '另外，成员内部类允许定义静态方法，在外嵌类的外部被引用时，需使用“外嵌类名.内部类名.静态方法”进行调用。', 355, 4),
(1764, 194, 172, 1, '程序清单 8-2 展示了成员内部类实例的创建、成员内部类静态方法的定义及其调用、同名成员的隐藏现象。', 355, 5),
(1765, 194, 172, 1, '运行结果如下：', 356, 1),
(1766, 194, 172, 1, '程序清单 8-2 第 1 行-第 10 行是一个测试类 InnerClassDemo1 的定义，该类只有一个主方法 main。第 12 行-38 行是外嵌类 OutterCls1 的定义，第 18 行-37 行是成员内部类 InnerCls1 的定义。', 356, 2),
(1767, 194, 172, 1, '程序清单 8-2 第 3 行-5 行在外嵌类 OutterCls1 作用域外创建了一个内部类对象 inner，在第 6 行使用了内部类对象，第 7 行调用了成员内部类定义的静态方法 getCount。静态方法 getCount 定义在第 34 行-36 行。', 356, 3),
(1768, 194, 172, 1, '程序清单 8-2 第 13 行定义了外嵌类 OutterCls1 的一个整型成员变量 i，第 19 行定义了成员内部类 InnerCls1 的一个整型成员变量 i。这里会出现变量隐藏现象。在成员内部类 InnerCls1 内部引用 i 时，引用的是内部类自身的成员变量 i，如第 26 行所示。为了引用外嵌类 OutterCls1 的成员变量 i，内部类 InnerCls1 定义了一个方法 getOutterI，如第 30 行-32 行所示。', 356, 4),
(1769, 194, 172, 1, '虽然成员内部类可以访问外嵌类的所有成员，但是，反过来，外嵌类却不能直接访问成员内部类的成员。如果要在外嵌类中访问成员内部类的成员，必须先创建一个成员内部类的对象，再通过这个对象的引用来访问成员内部类的成员。', 356, 5),
(1770, 194, 172, 1, '程序清单 8-3 给出了一个外嵌类访问内部类成员的示例。外嵌类在访问内部类时，不能直接访问，如果直接访问会出现编译错误，如程序清单 8-3 第 6 行所示。然而，外嵌类可以通过内部类对象访问，如程序清单 8-3 第 7 行所示，第 7 行调用了内部类的实例方法。', 356, 6),
(1771, 194, 172, 1, '运行结果如下：', 357, 1),
(1772, 194, 172, 1, '程序清单 8-3 第 4 行-14 行是外嵌类的两个构造方法。第 15-18 行是重写方法 toString()，第 20-22 行是返回一个内部类实例的方法 getDrawInstance()，第 23-29 行是成员内部类 Draw 的定义，第 30-35 行是主方法 main 的定义。', 357, 2),
(1773, 194, 172, 1, '程序清单 8-3 第 3 行定义了外嵌类 CircleNestDemo2 的一个私有成员变量 radius，内部类 Draw 可以直接访问，如第 26 行所示。在第 24 行内部类 Draw 定义了一个包访问成员变量 color，外嵌类是不能直接访问的，如第 6 行所示。在第 12 行，外嵌类通过内部类对象的引用访问成员变量 color 就是允许的。', 357, 3),
(1774, 195, 173, 1, '局部内部类是指定义在外嵌类的方法里面或者一个语句块作用域里面的类。局部内部类的访问权限仅限于方法内或者该语句块作用域内，而且，局部内部类与方法的局部变量一样，不能用 public、protected、private 以及 static、sealed 修饰符进行修饰。因此，局部内部类对外部世界是完全隐藏的，体现了更好的封装性。', 357, 4),
(1775, 195, 173, 1, '与成员内部类相比，局部内部类还有一个优势：局部内部类不仅能访问外嵌类的成员，还可以访问所在方法或所在语句块作用域内的局部变量。', 358, 1),
(1776, 195, 173, 1, '程序清单 8-4 给出了一个局部内部类的示例。', 358, 2),
(1777, 195, 173, 1, '运行结果如下所示：', 358, 3),
(1778, 195, 173, 1, '程序清单 8-4 第 8 行-13 行定义了一个局部内部类 Apple，该局部内部类实现了 Eatable 接口（第 21 行-23 行定义）。于是，局部内部类 Apple 对接口中的抽象方法 howToEat 进行了重写，如第 9 行-第 12 行所示。局部内部类 Apple 能够直接访问方法 eatFruit 中定义的局部变量 eatInfo，如第 11 行所示。第 2 行-第 4 行针对接口 Eatable 进行编程，编写静态方法 info()。第 5 行-16 行编写静态方法 eatFruit()，该方法内部定义了局部内部类 Apple。局部内部类 Apple 除了方法 eatFruit()能够访问，其他任何地方都不能被访问。第 14 行创建了一个局部内部类的对象 apple，等价于：Apple apple = Apple()。第 15 行以对象 apple 作为参数调用方法 info，输出信息。第 18 行在方法 main 中调用方法 eatFruit，输出信息：“水果的吃法：榨苹果汁”。', 358, 4),
(1779, 196, 174, 1, '在使用局部内部类的场景中，如果局部内部类的名称只被使用一次，仅用于创建这个局部内部类的对象，那么可以对局部内部类进行简化，可以无需指定局部内部类的类名。这样的一个没有名字的局部内部类被称为匿名内部类。', 358, 5),
(1780, 196, 174, 1, '程序清单 8-5 给出了一个匿名内部类的示例。', 358, 6),
(1781, 196, 174, 1, '程序清单 8-5 的运行结果与程序清单 8-4 一样，其简化对应关系：程序清单 8-4 的第 8 行-14 行被简化成程序清单 8-5 的第 7 行-12 行，如图 8-2 所示。（图 8-2　局部内部类与匿名内部类对应示例：a) 左侧是先定义局部内部类 Apple 实现 Eatable 接口，再单独创建对象；b) 右侧是在 new Eatable() 的类体中直接重写 howToEat() 并同时创建对象，两侧方法体内容相同）', 359, 1),
(1782, 196, 174, 1, '程序清单 8-5 的第 7 行-12 行的含义如下：创建一个类的新对象，该类实现了 Eatable 接口，在该类的方法体中对 Eatable 接口的抽象方法进行了重写。', 359, 2),
(1783, 196, 174, 1, '通常，匿名内部类的语法形式如下：', 359, 3),
(1784, 196, 174, 1, '这里的父类型既可以是接口，如程序清单 8-5 的 Eatable，也可以是一个类（通常是抽象类）。当父类型是接口时，父类型构造方法参数列表为空，调用的构造方法是 Object()，语法形式可以简化为：', 359, 4),
(1785, 196, 174, 1, '匿名内部类还具有以下几个特点：', 360, 1),
(1786, 196, 174, 1, '一个匿名内部类没有类名，而构造方法的名称必须与类名相同，因此，匿名内部类没有构造方法定义。', 360, 2),
(1787, 196, 174, 1, '一个匿名内部类必须实现父类型的所有抽象方法，因为匿名内部类自身不能是抽象的。', 360, 3),
(1788, 196, 174, 1, '每个匿名内部类都有自己对应的字节码文件，字节码文件命名形式是：外嵌类类名$n.class，在美元符号$后的符号 n 表示从 1 开始编号的整数。例如，程序清单 8-5 的源代码产生了两个字节码文件：AnnonymousInnerClassDemo.class、AnnonymousInnerClassDemo$1.class。如果一个外嵌类有多个匿名内部类，那么这些匿名内部类的文件名从数字 1 开始编号命名，即：外嵌类类名$1.class、外嵌类类名$2.class、外嵌类类名$3.class、…。', 360, 4),
(1789, 197, 175, 1, '用关键字 static 显式修饰的内嵌类是静态内嵌类，静态内嵌类没有对外嵌类对象的引用。显式声明静态内嵌类的一般形式如下所示：', 360, 5),
(1790, 197, 175, 1, '修饰符 1 可以使用 public 或缺省（无修饰符），修饰符 2 可以是 public、protected、privated 或缺省。', 360, 6),
(1791, 197, 175, 1, '除了显式声明的静态内嵌类，隐式声明的静态内嵌类包括：成员枚举类、局部枚举类、成员记录类、局部记录类、一个接口的成员类。', 360, 7),
(1792, 197, 175, 1, '静态内嵌类与成员内部类不同，不再持有外嵌类的引用，即不能使用“外嵌类名.this”引用外嵌类的实例成员。因此，静态内嵌类不能访问外嵌类的实例成员。静态内嵌类可以通过外嵌类的类名访问外嵌类的静态成员。', 360, 8),
(1793, 197, 175, 1, '静态内嵌类对象的创建语法形式如下：', 360, 9),
(1794, 197, 175, 1, '程序清单 8-6 给出了一个静态内嵌类的示例。', 360, 10),
(1795, 197, 175, 1, '运行结果：', 361, 1),
(1796, 197, 175, 1, '程序清单 8-6 第 1 行-7 行是测试类 StaticNestedClsDemo 的定义，第 8 行-第 21 行是外嵌类 OutterCls 的定义，第 12 行-20 行是静态内嵌类 StaticInner 的定义。', 361, 2),
(1797, 197, 175, 1, '程序清单 8-6 第 4 行创建了一个静态内嵌类对象 inner，第 5 行通过 inner 对象调用了方法 show()。第 9 行、第 10 行、11 行分别定义了外嵌类 OutterCls 的实例成员变量 i 和静态成员变量 k、m。第 13 行、14 行、15 行分别定义了静态内部类 StaticInner 的实例成员变量 i、静态成员变量 j、k。第 17 行访问了变量 i、j、k，这三个值都是静态内部类 StaticInner 的成员变量值。静态内部类的静态成员变量 k 隐藏外嵌类的静态成员 k，为了访问外嵌类的静态成员 k，可以使用外嵌类类名访问，如第 18 行“OutterCls.k”。当静态内部类访问外嵌类中未被隐藏的静态成员时，可以省略外嵌类类名，如第 18 行访问 m 的情况。', 361, 3),
(1798, 198, NULL, 1, 'lambda 表达式是 JAVA SE 8 提供的一种新特性，可以看做是一段可以传递的代码。在 Java 语言中，lambda 表达式还可以被称为闭包或匿名函数。lambda 表达式体现了函数式编程的思想：对行为进行抽象。', 361, 4),
(1799, 199, 176, 1, 'lambda 表达式一个直观的好处，就是可以简化匿名内部类的代码，使得程序员不再纠缠于匿名内部类的冗繁和可读性。', 361, 5),
(1800, 199, 176, 1, '下面用 lambda 表达式改写程序清单 8-5 的示例，说明 lambda 表达式如何替代匿名内部类，如程序清单 8-7 所示。', 361, 6),
(1801, 199, 176, 1, '程序清单 8-7 在改写程序清单 8-5 的示例时，为了避免和程序清单 8-5 使用的接口重名，将接口名修改为 EatMethod，接口内的方法 howToEat 不变，并给接口增加了一个注解@FunctionalInterface，表示接口 EatMethod 是一个函数式接口(Functional Interface)。函数式接口是一个不能使用关键 seal 修饰、必须有且只有一个抽象方法（除了 Object 的 public 方法）的接口。函数式接口可以使用注解@FunctionalInterface 进行修饰，其作用仅仅在于强迫 Java 编译器对接口进行语法检查，是否只定义了一个抽象方法，如果否，Java 编译器就会报错。程序清单 8-7 不使用注解@FunctionalInterface，也能正确运行。因此，函数式接口也可以被成为单抽象方法（Single Abstract Method，SAM）接口。', 362, 1),
(1802, 199, 176, 1, 'lambda 表达式可以简化函数式接口的实现，例如，程序清单 8-7 第 8 行的代码（lambda 表达式实现函数式接口）可以替换程序清单 8-5 第 7 行至 12 行的代码（匿名内部类实现函数式接口），替换关系如图 8-3 所示，lambda 表达式显然是更加直观简洁的表达，抽象出接口 EatMethod 具有的行为。（图 8-3　lambda 表达式替换匿名内部类示例 1：上方是 lambda 表达式赋值语句，其括号部分被标注为“参数列表”，花括号部分被标注为“方法体”；下方是被它替换的匿名内部类创建对象语句）', 362, 2),
(1803, 199, 176, 1, '结合示例，进一步展开说明：', 362, 3),
(1804, 199, 176, 1, '(1)lambda 表达式由三个部分组成：参数列表、箭头、方法体，一般语法形式如下：', 362, 4),
(1805, 199, 176, 1, '参数列表是由圆括号括起来的零个或多个参数，多个参数之间使用逗号分隔，对应函数式接口中抽象方法的参数列表。箭头是符号->，相当于一个分隔符。方法体是花括号括起来的零条或多条语句组成，对应匿名内部类对抽象方法重写的方法体。例如，lambda 表达式：() -> { return eatInfo + "：榨苹果汁"; }，参数列表为空，对应抽象方法 howToEat 的参数列表，方法体对应了匿名内部类对抽象方法 howToEat 进行重写的方法体，参数列表和方法体之间采用箭头->分隔。', 362, 5),
(1806, 199, 176, 1, '(2) 程序清单 8-7 第 8 行必须先指定 apple 对象的类型是 EatMethod，这样 Java 编译器就可以推断出赋值语句右边的表达式返回的是一个实现了函数式接口 EatMethod 的匿名类对象。', 362, 6),
(1807, 199, 176, 1, '(3) lambda 表达式的参数列表既可以和函数式接口中抽象方法的参数列表完全一致，也可以省略参数列表中的数据类型，此时参数的数据类型由编译器隐式推断。当参数列表只有一个参数时，圆括号可以省略。当参数列表为空时，必须要使用一对圆括号。', 363, 1),
(1808, 199, 176, 1, '(4) lambda 表达式的方法体如果只有一条语句，那么方法体部分的花括号可以省略。并且，如果这一条语句是 return 语句，可以省略关键字 return。因此，程序清单 8-7 第 8 行可以进一步简化为：', 363, 2),
(1809, 199, 176, 1, '(5) 程序清单 8-7 第 8 行-9 行，可以简化为如下一条语句：', 363, 3),
(1810, 199, 176, 1, '此时，lambda 表达式直接替换了方法的参数，而且分号;是不需要的。由于方法 info 的形参类型确定为接口类型 EatMethod，所以 Java 编译器会推断出这个 lambda 表达式是返回一个实现了函数式接口 EatMethod 的匿名类对象。', 363, 4),
(1811, 199, 176, 1, '(6) lambda 表达式能用于简化函数式接口的实现，对于函数式接口的定义需要准确理解。函数式接口不仅要有一个抽象方法，而且该抽象方法不能是类 Object 的 public 方法，例如，下面的一个接口定义就不是一个函数式接口：', 363, 5),
(1812, 199, 176, 1, '这是因为方法 equals()是类 Object 的 public 方法。', 363, 6),
(1813, 199, 176, 1, '然而，接口 NonFunc 的子接口可以是函数式接口，只要这个子接口声明了一个不是类 Object 成员的抽象方法，例如：', 363, 7),
(1814, 199, 176, 1, '同样地，Java 语言提供的有用接口 java.util.Comparator<T>是一个函数式接口，因为它只有一个不是类 Object 成员的抽象方法 compare(T o1, T o2)，另一个抽象方法 equals(Object obj)是类 Object 的 public 方法，java.util.Comparator<T>的定义如下：', 363, 8),
(1815, 199, 176, 1, '下面定义的一个接口 Func 具有一定的混淆性：定义了一个抽象方法 m()，定义了一个抽象方法 clone()。类 Object 有一个成员方法是 clone()，接口 Func 的定义与接口 Comparator<T>有些类似，那么，接口 Func 是否函数式接口呢？', 363, 9),
(1816, 199, 176, 1, '答案是：接口 Func 不是函数式接口。这是因为类 Object 的成员方法 clone()是 protected 方法，不是类 Object 的 public 方法。于是，接口 Func 定义了两个 public 抽象方法，因此，接口 Func 不是函数式接口。', 363, 10),
(1817, 199, 176, 1, '程序清单 8-7 给出的示例中 lambda 表达式是不带参数的。为了展示 lambda 表达式带有 1 个、2 个参数的情况，下面程序清单 8-8 给出了一个示例。', 363, 11),
(1818, 199, 176, 1, '运行结果：', 364, 1),
(1819, 199, 176, 1, '程序清单 8-8 第 24 行-27 行定义了一个函数式接口 Min，有一个抽象方法 handle()，带有一个形参。第 28 行-31 行定义了另一个函数式接口 MaxMin，有一个抽象方法 handle()，带有两个形参。第 3 行-6 行定义了一个方法 printMin，有两个形参：一个形参是接口类型 Min，另一个形参是一个整数数组。第 7 行-10 行定义了一个方法 printMaxMin，有两个形参：一个形参是接口类型 MaxMin，另一个形参是一个整数数组。', 364, 2),
(1820, 199, 176, 1, '程序清单 8-8 第 11 行-22 行是 main 方法的定义，测试了 lambda 表达式的各种使用情况。首先，第 12 行定义了一个整型数组 a。其次，第 13 行-18 行展示了具有一个参数的 lambda 表达式的使用情况。接着，第 19 行-21 行展示了具有两个参数的 lambda 表达式的使用情况。', 365, 1),
(1821, 199, 176, 1, '具体地，第 14 行调用了方法 printMin，该方法的第一个实参是一个具有一个参数的 lambda 表达式，也是一个完整形式的 lambda 表达。第 14 行代码也等价于如下代码：', 365, 2),
(1822, 199, 176, 1, '程序清单 8-8 第 16 行-18 行是 lambda 表达式的各种省略形式。第 18 行省略了参数的数据类型，第 19 行省略了圆括号，第 20 行省略了花括号和分号。', 365, 3),
(1823, 199, 176, 1, '程序清单 8-8 第 20 行调用了方法 printMaxMin，该方法的第一个实参是一个具有两个参数的 lambda 表达式，也是一个完成形式的 lambda 表达式。第 21 行是省略了数据类型和花括号的 lambda 表达式使用情况。当 lambda 表达式中有两个参数时，圆括号不能省略。', 365, 4),
(1824, 199, 176, 1, '因此，lambda 表达式的省略规则如下：', 365, 5),
(1825, 199, 176, 1, '(1) lambda 表达式参数列表中参数的数据类型可以省略，而且必须同时省略，不允许省略其中一部分参数的数据类型，而另一部分参数不省略。', 365, 6),
(1826, 199, 176, 1, '(2) 在 lambda 表达式省略参数的数据类型之后，如果参数列表只有一个参数时，圆括号可以省略。其他情况下，圆括号不能省略。具体地，当参数列表为空时，不能省略圆括号；当参数列表中的参数个数不少于 2 个时，也不能省略圆括号。', 365, 7),
(1827, 199, 176, 1, '(3) 当 lambda 表达式方法体中的语句只有一条时，可以省略花括号和分号。进一步，当这一条语句是 return 语句时，return 也必须省略。', 365, 8),
(1828, 199, 176, 1, '通过上面的示例，可以看出，Java 编译器在解析一个 lambda 表达式时，等同于是从一个匿名内部类创建一个匿名对象。通常，Java 编译器处理 lambda 表达式有三个步骤：①确定 lambda 表达式的数据类型；②确定参数的数据类型；③确定语句。例如，针对程序清单 8-8 第 18 行：', 365, 9),
(1829, 199, 176, 1, 'Java 编译器可以根据方法 printMin()的形参类型可以推断出 lambda 表达式的数据类型是实现了函数式接口 Min 的匿名对象。然后，根据函数式接口 Min 的抽象方法 handle()只有一个整型形参，推断出参数 min 的数据类型是整型。最后，基于箭头->后的语句，确定重写抽象方法 handle()的方法体。', 365, 10),
(1830, 200, 177, 1, 'lambda 表达式的体与嵌套块具有相同的作用域。因此，在 lambda 表达式中声明一个与外部作用域同名的局部变量是不合法的。', 365, 11),
(1831, 200, 177, 1, '与嵌套块一样，lambda 表达式可以访问外围方法或类中的变量，例如，程序清单 8-7 的第 8 行：', 365, 12),
(1832, 200, 177, 1, 'lambda 表达式中出现的变量 eatInfo 就是程序清单 8-7 的第 8 行定义的变量，是 lambda 表达式外部的变量。因此，lambda 表达式可以捕获(或访问)外围作用域中变量的值。', 365, 13),
(1833, 200, 177, 1, '然而，lambda 表达式访问外围方法或类中的变量，有一个重要的限制：只能引用外部变量的值而不能改变外部变量的值。并且，如果在 lambda 表达式中引用了一个外部变量，这个外部变量也不能在外部改变。因此，lambda 表达式与嵌套块不同的地方在于，lambda 表达式访问外围作用域的变量必须是最终变量（即常量）或事实最终(effective final)变量。事实最终变量是指一个变量被初始化后就不再为其赋新值。', 365, 14),
(1834, 200, 177, 1, '因此，lambda 表达式中引用的外部变量是有具体限制的：一方面，lambda 表达式不能对引用的外部变量进行修改；另一方面，如果 lambda 表达式引用了一个外部变量，这个外部变量就成为事实最终变量，在外部作用域中，不允许对其进行修改。', 366, 1),
(1835, 200, 177, 1, '下面通过一个例子说明 lambda 表达式作用域，以及 lambda 表达式引用外部变量所遇到的限制，如程序清单 8-9 所示。', 366, 2),
(1836, 200, 177, 1, '运行结果为：', 366, 3),
(1837, 200, 177, 1, '程序清单 8-9 第 19 行-22 行定义了一个函数式接口 Max。第 2 行-第 4 行定义了一个静态方法 printMax()，具有两个形参：一个是接口类型 Max，一个是整型数组。第 6 行定义了一个整型数组，第 7 行、8 行、9 行分别定义了三个局部变量。第 11 行-15 行调用了方法 printMax()，该方法的第一个参数是一个 lambda 表达式，第二个参数是整型数组 a。其中，第 11 行如果把第一个注释符去掉，Java 编译器会报错，lambda 表达式访问外部变量时，不能修改外部变量的值。第 12 行如果把第一个注释符去电，Java 编译器也会报错，这是因为在嵌套的作用域不能定义与外部作用域同名的变量。第 16 行如果把第一个注释符去掉，Java 编译器也会报错，这是因为第 14 行在 lambda 表达式中引用了 count，此时，变量 count 成为事实最终变量，不允许在外部作用域进行修改。', 366, 4),
(1838, 201, 178, 1, '引入 lambda 表达式主要是为了简化函数式接口的实现。因此，在 lambda 表达式中，不应该出现比较复杂的逻辑。如果 lambda 表达式的逻辑过于复杂，就会对程序的易读性造成不好的影响。如果 lambda 表达式需要处理比较复杂的逻辑，可以单独编写一个方法，在 lambda 表达式进行直接引用，这就是方法引用。方法引用也称为函数引用，是指在 lambda 表达式中引用一个已经存在的方法，使其替代 lambda 表达式完成接口的实现。', 366, 5),
(1839, 201, 178, 1, '根据方法引用的方法类型，可以分为静态方法引用、实例方法引用、构造方法引用，下面对这三种引用形式分别进行介绍。', 367, 1),
(1840, 201, 178, 1, '首先，静态方法引用的一般语法形式：', 367, 2),
(1841, 201, 178, 1, '程序清单 8-10 给出了一个静态方法引用的示例。', 367, 3),
(1842, 201, 178, 1, '运行结果：', 367, 4),
(1843, 201, 178, 1, '程序清单 8-10 第 28 行-31 行定义了一个函数式接口，第 20 行-27 行定义了一个 Calculator 类，Calculator 类内部有一个静态方法 subtraction。第 3 行-6 行通过键盘输入了两个 double 类型值。第 8 行是 lambda 表达式的静态方法引用，可理解为，lambda 表达式由 Calculator 类的静态方法 subtraction 替代。第 10 行-15 行是 lambda 表达式的原始形式，所有处理逻辑放在 lambda 表达式的方法体部分。从这里，可以看出，通过第 8 行的静态方法引用，可以把 lambda 表达式的复杂逻辑提取出来放置到某个类的静态方法。这里需要注意的是：', 368, 1),
(1844, 201, 178, 1, '(1) 静态方法引用，只需要静态方法名，不需要在方法名后加圆括号。例如，程序清单 8-10 第 8 行只引用了静态方法名。', 368, 2),
(1845, 201, 178, 1, '(2) 被引用的静态方法的参数列表和返回值，与 lambda 表达式实现的接口中抽象方法的参数列表和返回值一致。被引用的静态方法的方法体，与 lambda 表达式的方法体一致。例如，程序清单 8-10 第 21 行定义的方法 subtraction，其参数列表与 lambda 表达式的参数列表一致，即与函数式接口 SubInterface1 的抽象方法 handle()的参数列表一致；其方法体与 lambda 表达式的方法体一致，如程序清单 8-10 第 10 行-15 行所示。', 368, 3),
(1846, 201, 178, 1, '其次，实例方法引用的一般语法形式：', 368, 4),
(1847, 201, 178, 1, '程序清单 8-11 给出了实例方法引用的示例', 368, 5),
(1848, 201, 178, 1, '运行结果如下：', 369, 1),
(1849, 201, 178, 1, '程序清单 8-11 第 28 行-31 行定义了一个函数式接口，第 19 行-27 行定义了一个静态内嵌类 Calculator，其内部只定义了一个实例方法 subtraction。第 3 行-6 行输入两个浮点数。第 8 行是 lambda 表达式的实例方法引用，可理解为，lambda 表达式由 Calculator 类的实例方法 subtraction 替代。由于不是静态方法，所以第 8 行使用 new Calculator()创建了一个匿名 Calculator 对象，然后再通过::引用实例方法名。第 10 行-15 行是 lambda 表达式原始形式，所有处理逻辑放在 lambda 表达式的方法体部分。从这里，可以看出，通过第 8 行的实例方法引用，可以把 lambda 表达式的复杂逻辑提取出来放置到某个类的实例方法。这里需要注意的是：', 369, 2),
(1850, 201, 178, 1, '(1) 实例方法引用与静态方法不同，需要使用对象名，对象名可以是匿名的。', 369, 3),
(1851, 201, 178, 1, '(2) 实例方法引用，只需要实例方法名，不需要在方法名后加圆括号。', 369, 4),
(1852, 201, 178, 1, '(3) 被引用的实例方法的参数列表和返回值，与 lambda 表达式实现的接口中抽象方法的参数列表和返回值一致。被引用的实例方法的方法体，与 lambda 表达式的方法体一致。', 369, 5),
(1853, 201, 178, 1, '最后，构造方法引用的一般语法形式：', 369, 6),
(1854, 201, 178, 1, '程序清单 8-12 给出了构造方法引用的示例。', 369, 7),
(1855, 201, 178, 1, '运行结果如下：', 370, 1),
(1856, 201, 178, 1, '程序清单 8-12 第 19 行-37 行定义了一个学生类 Student，其内部定义了三个成员变量，两个构造方法。第 38 行-41 行定义了函数式接口 CreateStudent1，其内部定义了一个有 3 个参数的抽象方法返回一个 Student 对象。第 42 行-45 行定义了函数式接口 CreateStudent2，其内部定义了一个不带参数的抽象方法返回一个 Student 对象。', 370, 2),
(1857, 201, 178, 1, '第 4 行是 lambda 表达式的构造方法引用，由于对象 cstu1 的类型实现了接口 CreateStudent1，而接口 CreateStudent1 内部有一个带三个参数的抽象方法 create()，因此，这个构造方法引用表示引用的是 Student 类带三个参数的构造方法。第 6 行是 lambda 表达式原始形式实现接口 CreateStudent1。第 11 行也是 lambda 表达式的构造方法引用，赋值运算符右边与第 4 行一样，然而，由于这里实现的接口是 CreateStudent2，其内部是一个不带参数的抽象方法 create()，因此这个构造方法引用表示引用的是 Student 类不带参数的构造方法。因此，对比第 4 行代码和第 6 行代码，可以看出，函数式接口中抽象方法的不同，导致对应的构造方法会不同。第 13 行代码是 lambda 表达式原始形式的简略形式。', 370, 3),
(1858, 201, 178, 1, '上述三种形式的方法引用，可以使代码简洁，提升程序的易读性。', 371, 1),
(1859, 202, 179, 1, 'ArrayList 中有两个方法可以使用 lambda 表达式，这两个方法是：forEach()、removeIf。', 371, 2),
(1860, 202, 179, 1, '该方法可对当前列表的每个元素执行给定的操作，直到处理完所有元素或该操作引发异常为止。如果指定了迭代顺序，则操作将按迭代顺序执行。操作引发的异常会中继到调用方。', 371, 3),
(1861, 202, 179, 1, '该方法删除当前列表中满足给定谓词（即某种条件）的所有元素。迭代期间或谓词引发的错误或运行时异常会中继到调用方。', 371, 4),
(1862, 202, 179, 1, '程序清单 8-13 给出了使用上面两个方法的示例。', 371, 5),
(1863, 202, 179, 1, '运行结果如下：', 371, 6),
(1864, 202, 179, 1, '程序清单 8-13 第 3 行、4 行创建了一个具有初值的列表。第 6 行调用了 forEach 方法，其参数是 lambda 表达式的实例方法引用，第 7 行也调用了 forEach 方法，其参数是 lambda 表达式的原始形式，在输出时，列表各元素之间增加了一个空格。第 10 行-14 行也是调用 forEach 方法，在输出列表元素时，将奇数过滤了。第 15 行调用了 removeIf 方法删除列表中偶数，通过指定谓词：e%2 == 0。第 18 行通过 forEach 方法验证了删除后的结果。', 371, 7),
(1865, 203, 180, 1, 'Java 语言提供的接口 java.util.Comparator<T>是一个函数式接口，它有一个抽象方法：', 372, 1),
(1866, 203, 180, 1, '该方法接受两个对象作为参数，并返回一个 int 值，表示它们的顺序。', 372, 2),
(1867, 203, 180, 1, '类 Collections 具有一个静态方法 sort，能够对列表对象进行排序，sort 方法的定义如下：', 372, 3),
(1868, 203, 180, 1, '第一个参数是 List<T>，该类型是 ArrayList<E>的父类型，因此，Collections.sort()可以对 ArrayList 对象进行排序。第二个参数的类型 Comparator 接口类型，该接口是一个函数式接口，因此第二个参数可以用 lambda 表达式，也可以用匿名内部类对象。', 372, 4),
(1869, 203, 180, 1, '程序清单 8-14 给出了一个使用 Comparator 接口的示例，综合应用了匿名内部类，lambda 表达式。该示例能够按自定义比较标准，比较两个学生对象，结合方法 Collections.sort()得到学生列表按某一标准的升序或降序排列结果。', 372, 5),
(1870, 203, 180, 1, '运行结果如下：', 374, 1),
(1871, 203, 180, 1, '程序清单 8-14 第 64 行-77 行定义了一个学生类 Pupils，并提供了两个构造方法。第 3 行-第 9 行定义了一个学生数组，具有 5 个学生对象。第 10 行基于学生对象创建了一个列表 list。第 13 行-22 行调用了 Collections.sort()方法，其第二个参数采用匿名内部类形式创建了一个匿名内部类对象。第 15 行-21 行重写了抽象方法 compare()，按学号 ID 的升序进行排序。第 23 行调用 forEach 方法，传递 lambda 表达式作为参数，输出按学号升序排序后的结果。第 26 行-32 行也调用了 Collections.sort()方法，其第二个参数采用 lambda 表达式，该 lambda 表达式的方法体采用降序比较器，见第 27 行-28 行。第 33 行也是调用 forEach 方法，传递 lambda 表达式作为参数，输出按学号降序排序后的结果。第 36 行调用了 Collections.sort()方法，其第二个参数采用静态方法引用，引用的方法在第 45 行-51 行。该静态方法位于私有静态内嵌类 HeightAscComparator 中（第 44 行-52 行），其代码体现了按身高升序排列。类似地，第 40 行调用了 Collections.sort()方法，其第二个参数采用实例方法引用，引用的方法在第 55 行-62 行。该实例方法位于私有静态内嵌类 HeightDecComparator 中（第 54 行-62 行），其代码体现了按身高降序排列。', 374, 2),
(1872, 204, 181, 1, '对应章节：8.1 内部类', 374, 3),
(1873, 204, 181, 1, '思政教学目标：', 374, 4),
(1874, 204, 181, 1, '① 加深学生对民主集中制这一党的组织原则和领导制度的理解', 374, 5),
(1875, 204, 181, 1, '② 鼓励学生积极参与党内民主活动', 374, 6),
(1876, 204, 181, 1, '③ 培养学服从集体、服从中央工作部署的自觉意识', 374, 7),
(1877, 204, 181, 1, '思政教学设计：', 374, 8),
(1878, 204, 181, 1, '民主集中制是我们党的根本组织原则和领导制度，是马克思主义政党区别于其他政党的重要标志。在中国经济社会发展的实际运行中，这项制度把充分发扬党内民主和正确实行集中领导有机结合起来，既最大限度激发了全党创造活力，又统一全党思想和行动，有效防止和克服了议而不决、决而不行的分散主义。在全面建设社会主义现代化国家的新征程中，要推进党建的伟大工程，必须确保实现党对一切工作的领导，必须坚持好、运用好民主集中制。', 374, 9),
(1879, 204, 181, 1, '2022 年 10 月 17 日上午，习近平总书记来到他所在的党的二十大广西代表团，同代表们深入讨论，一起审议党的二十大报告。广西代表团代表们踊跃发言，现场气氛热烈。党的代表大会是发扬民主集中制原则的重要载体，党代表听取和审议大会提交的一系列重要文件，踊跃参与讨论并依照法定程序决定党的重大问题是广泛发扬党内民主的重要一环。', 374, 10),
(1880, 204, 181, 1, '针对上述思政教学目标，运用类比分析的方法，把共产党这个大组织机构类比为一个外嵌类，党的代表大会则是其中的一个内部类，运用外嵌类和内部类的结构关系和功能关系，讲授局部和整体，地方中央的关系，在讲授中贯穿“个人服从党的组织，少数服从多数，下级组织服从上级组织，全党各个组织和全体党员服从党的全国代表大会和中央委员会”的基本组织原则。', 375, 1),
(1881, 204, 181, 1, '首先，从外嵌类和内部类的结构关系看，内部类是嵌套于外嵌类的类之中。那么共产党这个巨大的组织可以看做是一个外嵌类，其内部各级代表大会可以看做是共产党组织的内部类，从组织形式上看，它们是整体和局部的关系。', 375, 2),
(1882, 204, 181, 1, '其次，从内部类的功能特征看，内部类和外嵌类之间不可以机械的把内部类仅仅当成外嵌类的一个普通成员。比如，内部类除了有自己的成员属性外，还可以访问操作外嵌类的所有成员属性。这一特征使得内部类可以控制更多的资源，实现更加强大的功能。那么，就不可以机械、简单地把内部类当成外嵌类的普通成员。同理，党的各级代表大会其所能控制的资源，所具备的功能决定了其必然在党组织的运作中具备更大的权力，成为各级党组织的最高权力机构。所以，党员和党的其它部门应该自觉服从党代会的决定，遵守党代会制定的规章制度。这就确立了“全党各个组织和全体党员服从党的全国代表大会和中央委员会”的基本组织原则”。当然，党代会在运作中也要遵循民主原则，通过调动全党的智力资源和人力资源，保证做出的决策更加科学合理。调动智力资源的过程就相当于内部类访问外嵌类的成员，集思广益，做到了党内民主。', 375, 3),
(1883, 204, 181, 1, '最后总结，党的民主集中制的科学性、合理性、适用性。中国共产党是按马克思主义建党原则建立的政党，一开始就把民主集中制作为自己的组织原则和制度。在革命、建设和改革开放的各个历史时期，党的领导工作、组织工作以民主集中制为根本规范，这对于党的组织巩固、壮大，制定正确的路线方针政策，发挥了重要的保障作用。在中国特色社会主义新时代，要确保党的团结坚强有力，确保党的领导能力、领导水平不断提高，从制度角度来说，必须把坚持民主集中制贯彻落实到党的领导工作和组织建设实践中。', 375, 4),
(1884, 204, 181, 1, '案例反思', 375, 5),
(1885, 204, 181, 1, '思政案例的设计中需强调，民主集中制这一政治活动原则有其深刻的自然科学原理，或者说二者遵循了共同的哲学思想和原理。在进行自然科学讲授中可以无痕植入社会科学的知识。因此，应有机结合课堂教学内容，开展思政教育。', 375, 6);
