INSERT INTO `knowledge_difficult_point` (`id`, `chapter_id`, `description`, `type`, `page`, `page_order`) VALUES
(95, 194, '同名成员隐藏：成员内部类与外嵌类有同名成员变量或方法时，内部类中默认访问的是内部类自己的成员，要访问外嵌类成员必须写成“外嵌类名.this.成员变量/成员方法”，如 CircleNestDemo.this.radius，直接写成员名将得到内部类的值。', 1, 354, 1),
(96, 194, '字节码文件命名（实名内部类）：外嵌类名$实名内部类名.class，如 CircleNestDemo.java 编译后产生 CircleNestDemo.class 和 CircleNestDemo$Draw.class 两个文件，选择题常考。', 2, 354, 2),
(97, 194, '成员内部类实例不能写成 new OutterCls1.InnerCls1()，必须先在外部创建外嵌类实例，再用“外嵌类实例名.new 内部类类名(参数列表)”创建；引用内部类静态方法则写成“外嵌类名.内部类名.静态方法”。', 1, 355, 1),
(98, 194, '访问方向不对称：成员内部类可以访问外嵌类的所有数据域和成员方法（包括 private 和静态成员），但外嵌类不能直接访问内部类的成员，必须先创建内部类对象再通过引用访问，否则编译报错。', 3, 356, 1),
(99, 195, '局部内部类与方法的局部变量一样，不能用 public、protected、private 以及 static、sealed 修饰，访问权限仅限于方法内或语句块作用域内，因此在方法外任何地方都无法访问它。', 2, 357, 1),
(100, 196, '匿名内部类三特点易错：没有类名因而没有构造方法定义；自身不能是抽象的，必须实现父类型的所有抽象方法；字节码文件名为外嵌类类名$n.class，n 是从 1 开始编号的整数，多个匿名内部类依次为$1、$2、$3。', 3, 360, 1),
(101, 197, '静态内嵌类与内部类的辨析：静态内嵌类不再持有外嵌类的引用，不能使用“外嵌类名.this”，因而不能访问外嵌类的实例成员，只能通过外嵌类类名访问外嵌类的静态成员；内嵌类分为内部类和静态内嵌类两支，静态内嵌类不属于内部类。', 3, 360, 1),
(102, 199, '函数式接口的判定易错：抽象方法必须不是类 Object 的 public 方法。equals()是 Object 的 public 方法，只声明它的接口 NonFunc 不是函数式接口；clone()在 Object 中是 protected 方法，因此同时声明 m()和 Object clone()的接口 Func 有两个 public 抽象方法，也不是函数式接口。', 1, 363, 1),
(103, 199, 'lambda 表达式的省略规则有约束：参数数据类型要么全省略要么都不省略；只有省略数据类型后且参数列表仅一个参数时才能省略圆括号，参数列表为空或参数不少于 2 个时圆括号不能省略；方法体只有一条语句时才能省略花括号和分号，该语句为 return 语句时 return 也必须省略。', 2, 365, 1),
(104, 200, 'lambda 表达式与嵌套块作用域相同，体内声明与外部作用域同名的局部变量不合法；引用的外围变量必须是最终变量（常量）或事实最终变量，既不能在 lambda 体内改写（如 i++），也不能在外部改写（如 count--），否则编译报错。', 1, 366, 1),
(105, 201, '方法引用不是调用：静态方法引用只写静态方法名且不带圆括号；实例方法引用需要对象名（可以匿名）；构造方法引用“类名::new”具体匹配哪个构造方法，完全由函数式接口抽象方法的参数列表决定，接口不同则引用的构造方法不同。', 2, 370, 1),
(106, 202, 'removeIf 的谓词方向与 forEach 的输出累加易错：removeIf(e -> e%2 == 0)删除偶数留下奇数，谓词为 case-sensitive 时 removeIf(e -> e.equals("White"))只删“White”不删“white”；forEach 用 print 连接输出无分隔符，用 print(e + " ")元素之间会有一个尾随空格。', 1, 371, 1),
(107, 203, 'compare 返回值的正负决定升降序：升序比较器写成 o1 大于 o2 返回 1、小于返回 -1；把 compareTo() < 0 返回 1（即交换正负）得到的是降序结果，Collections.sort()对同一列表多次调用会依次覆盖前一次顺序。', 1, 372, 1),
(108, 203, 'Collections.sort()第二个参数三种写法可互换：匿名内部类对象、lambda 表达式原始形式、方法引用（静态方法引用或实例方法引用），高频考点是能识别三者等价并写出按自定义字段升序或降序的比较逻辑。', 2, 372, 2),
(109, 204, '课程思政案例的类比要点：把党的组织类比为外嵌类、各级代表大会类比为内部类，说明整体与局部、地方与中央的关系；内部类可访问操作外嵌类的所有成员属性，对应党代会在党组织运作中具备更大权力，体现“全党各个组织和全体党员服从党的全国代表大会和中央委员会”。', 3, 375, 1);
INSERT INTO `knowledge_exercise` (`id`, `chapter_id`, `question`, `answer`, `difficulty`, `knowledge_point`, `page`, `page_order`) VALUES
(556, 192, '1、 假定 A 是 Test 类的一个内部类，A 被编译成一个单独的字节码文件，其文件名为（ ）。\n(A) A.class　(B) Test$A.class　(C) A$Test.class　(D)Test&A.class', 'B', 1, '成员内部类', 376, 1),
(557, 192, '2、 下列关于内部类描述错误的是( )\n(A) 内部类与外嵌类的成员方法一样，可以访问外嵌类的所有成员，包括私有成员\n(B) 内部类的访问权限可以被修饰为 public、protected、private 和 default\n(C) 静态内嵌类也是内部类的一种\n(D) 内部类可以定义静态成员，外嵌类可以通过内部类类名进行访问', 'C', 1, '静态内嵌类', 376, 2),
(558, 192, '3、 下列关于内部类的说法，正确的是（ ）。\n(A) 内部类可以与其外嵌类的类名相同\n(B) 内部类只能访问其外嵌类的实例成员，不能访问其外嵌类的静态成员\n(C) 内部类可以用 abstract 修饰声明为抽象的内部类\n(D) 在外嵌类的外部使用内部类时必须使用外嵌类名.内部类名', 'C', 1, '成员内部类', 376, 3),
(559, 192, '4、 在 Java 的内部类中，当内部类成员和外嵌类成员同名时，如何访问外嵌类成员？（ ）\n(A) 外嵌类名.this.成员　　(B) 外嵌类名.成员\n(C) 内部类名.this.成员　　(D) 内部类名.成员', 'A', 1, '成员内部类', 376, 4),
(560, 192, '5、 下面关于匿名内部类说法错误的是（ ）\n(A) 匿名内部类可以有构造方法　(B) 匿名内部类可以继承抽象父类\n(C) 匿名内部类可以实现接口　(D) 匿名内部类对象只能使用一次', 'A', 1, '匿名内部类', 376, 5),
(561, 192, '6、 关于 Java 中的匿名内部类，下列说法错误的是（ ）\n(A) 匿名内部类必须且仅能继承一个父类或实现一个接口\n(B) 匿名内部类不使用关键字 class，没有类名\n(C) 匿名内部类是成员内部类的一种特殊情况\n(D) 匿名内部类不能是抽象类', 'C', 1, '匿名内部类', 376, 6),
(562, 192, '7、 匿名内部类在编译后，其字节码文件的文件名是（ ）。\n(A) 外嵌类名$内部类名.class　　(B) 外嵌类名$n.class\n(C) 内部类名.class　　(D) 外嵌类名_n.class', 'B', 1, '匿名内部类', 376, 7),
(563, 192, '8、 关于 lambda 表达式，描述错误的是（ ）\n(A) lambda 表达式不能修改外围作用域的变量\n(B) 在 lambda 表达式中出现的参数，其数据类型必须显式声明\n(C) 在 lambda 表达式中，如果只有一个参数，包围参数的圆括号可省略\n(D) 编译器对待一个 lambda 表达式，如同它是从一个匿名内部类创建的对象', 'B', 1, 'lambda 表达式语法', 376, 8),
(564, 192, '9、 下列选项中符合 lambda 表达式语法的是（ ）。\n(A) x -> return x+1　　(B) x, y -> x + y\n(C) x -> {x=x*2; x+1;}　　(D) x -> { x=x*2; return x+1; }', 'D', 1, 'lambda 表达式语法', 376, 9),
(565, 192, '10、下列选项中不符合 Lambda 表达式语法的是（ ）。\n(A) x -> x+1　　(B) (x,y) -> x+y\n(C) (num) -> {return num+1;}　　(D) x, y ->{ return x+y;}', 'D', 1, 'lambda 表达式语法', 376, 10),
(566, 192, '1、 内嵌类可分为____________和________________。', '内部类（inner class）；静态内嵌类（static nest class）', 1, '教学目标', 377, 11),
(567, 192, '2、 实名内部类可为分：________________、________________。', '成员内部类；局部内部类', 1, '成员内部类', 377, 12),
(568, 192, '3、 隐式的静态内嵌类包括：________________、________________、成员记录类、局部记录类、________________。', '成员枚举类；局部枚举类；一个接口的成员类', 1, '静态内嵌类', 377, 13),
(569, 192, '4、 对于实名内部类，其字节码文件的文件名为：________________________。', '外嵌类名$实名内部类名.class', 1, '成员内部类', 377, 14),
(570, 192, '5、 当成员内部类拥有和外嵌类同名的成员变量或者方法时，会发生________________。', '隐藏现象（在成员内部类中，默认访问的是成员内部类的成员）', 1, '成员内部类', 377, 15),
(571, 192, '6、 成员内部类________________(能/不能)直接访问外嵌类的所有成员，外嵌类________________(能/不能)直接访问成员内部类的成员。', '能；不能', 1, '成员内部类', 377, 16),
(572, 192, '7、 ________________内部类对外部世界是完全隐藏的，体现了更好的封装性。', '局部', 1, '局部内部类', 377, 17),
(573, 192, '8、 局部内部类不仅能访问外嵌类的成员，还可以访问________________的局部变量。', '所在方法或所在语句块作用域内', 1, '局部内部类', 377, 18),
(574, 192, '9、 匿名内部类(能/不能)________定义构造方法。', '不能', 1, '匿名内部类', 377, 19),
(575, 192, '10、每个匿名内部类都有自己对应的字节码文件，字节码文件命名形式是：_____________。', '外嵌类类名$n.class（n 表示从 1 开始编号的整数）', 1, '匿名内部类', 377, 20),
(576, 192, '11、静态内嵌类对象的创建语法形式如下：______________________________________。', '外嵌类名.静态内嵌类 内部类对象名 = new 外嵌类名.静态内嵌类();', 1, '静态内嵌类', 377, 21),
(577, 192, '12、创建成员内部类实例的一般语法形式如下：__________________________________。', '外嵌类类名.内部类类名 内部类对象名 = 外嵌类实例名.new 内部类类名(参数列表);', 1, '成员内部类', 377, 22),
(578, 192, '13、在 Java 语言中，lambda 表达式还可以被称为________或匿名函数。lambda 表达式体现了函数式编程的思想：________________。', '闭包；对行为进行抽象', 1, 'lambda 表达式语法', 377, 23),
(579, 192, '14、lambda 表达式由三个部分组成：_________、__________、_____________。', '参数列表；箭头；方法体', 1, 'lambda 表达式语法', 377, 24),
(580, 192, '15、lambda 表达式的参数列表既可以和函数式接口中抽象方法的参数列表完全一致，也可以省略参数列表中的_________，此时参数的数据类型由_________隐式推断。当参数列表只有一个参数时，_________可以省略。', '数据类型；编译器；圆括号', 1, 'lambda 表达式语法', 377, 25),
(581, 192, '16、lambda 表达式的体与______________具有相同的作用域。', '嵌套块', 1, 'lambda 表达式作用域', 377, 26),
(582, 192, '17、当 lambda 表达式方法体中的语句只有一条时，可以省略____________。进一步，当这一条语句是 return 语句时，__________也必须省略。', '花括号和分号；return', 1, 'lambda 表达式语法', 377, 27),
(583, 192, '18、lambda 表达式与嵌套块不同的地方在于，lambda 表达式访问外围作用域的变量必须是________________________________。', '最终变量（即常量）或事实最终（effective final）变量', 1, 'lambda 表达式作用域', 377, 28),
(584, 192, '1、 程序中使用内嵌类的原因是什么？', '程序中使用内嵌类的原因主要有两个：一是内嵌类可以对同一包中的其它类隐藏，增强了代码的封装性。二是内嵌类方法可以访问定义该类的作用域中的属性和方法，包括作用域中的私有数据域。此外，内嵌类机制在设计相互合作的类时，有助于将相关类绑定在一起。', 2, '教学目标', 377, 29),
(585, 192, '2、 请描述内嵌类的分类。', '内嵌类可分为内部类（inner class）和静态内嵌类（static nest class），一个内部类是一个没有显式或隐式静态的内嵌类。内部类按照有无实名，可以分为实名内部类和匿名内部类，而实名内部类包括成员内部类、局部内部类。除了使用 static 关键字显式修饰的内嵌类，隐式的静态内嵌类包括：成员枚举类、局部枚举类、成员记录类、局部记录类、一个接口的成员类。', 2, '教学目标', 377, 30),
(586, 192, '3、 如果要在成员内部类中访问外嵌类的同名成员，该如何访问？', '当成员内部类拥有和外嵌类同名的成员变量或方法时会发生隐藏现象，此时成员内部类中默认访问的是成员内部类自己的成员。要在成员内部类中访问外嵌类的同名成员，需按“外嵌类名.this.成员变量”“外嵌类名.this.成员方法”的形式访问。例如类 Draw 要访问外嵌类 CircleNestDemo 的私有成员变量 radius，引用代码为 CircleNestDemo.this.radius。', 2, '成员内部类', 377, 31),
(587, 192, '4、 请简要描述匿名内部类的语法形式。', '匿名内部类的语法形式为：new 父类型名称(父类型构造方法参数列表){ 匿名内部类的成员方法和成员数据域定义; }。这里的父类型既可以是接口，也可以是一个类（通常是抽象类）。当父类型是接口时，父类型构造方法参数列表为空，调用的构造方法是 Object()，语法形式可简化为：new 接口名(){ 数据域定义；方法定义；}。', 2, '匿名内部类', 377, 32),
(588, 192, '5、 请简要描述静态内嵌类的语法形式。', '显式声明静态内嵌类的一般形式为：[修饰符 1]class OuterClass { [修饰符 2] static class NestedClass { … } }，其中修饰符 1 可用 public 或缺省，修饰符 2 可用 public、protected、private 或缺省。静态内嵌类对象的创建语法形式为：外嵌类名.静态内嵌类 内部类对象名 = new 外嵌类名.静态内嵌类();。静态内嵌类没有对外嵌类对象的引用，不能访问外嵌类的实例成员，只能通过外嵌类的类名访问其静态成员。', 2, '静态内嵌类', 377, 33),
(589, 192, '6、 什么是函数式接口？', '函数式接口是一个不能使用关键 seal 修饰、必须有且只有一个抽象方法（除了 Object 的 public 方法）的接口，因此也可被称为单抽象方法（Single Abstract Method，SAM）接口。该唯一抽象方法不能是类 Object 的 public 方法。函数式接口可用注解@FunctionalInterface 修饰，其作用仅在于强迫 Java 编译器检查接口是否只定义了一个抽象方法，不加该注解也能正确运行。', 2, 'lambda 表达式语法', 377, 34),
(590, 192, '7、 下面一个接口定义是否函数式接口？为什么？\n```java\ninterface FuncInterface1{\n      String toString();\n}\n```', '不是函数式接口。String toString()是类 Object 的 public 方法，按教材规定函数式接口的抽象方法不能是类 Object 的 public 方法，该接口中没有符合条件的抽象方法，因此不能用 lambda 表达式实现它。', 2, 'lambda 表达式语法', 377, 35),
(591, 192, '8、 下面一个接口定义是否函数式接口？为什么？\n```java\ninterface FuncInterface2{\n      String toString();\n      void handle(String s);\n}\n```', '是函数式接口。String toString()是类 Object 的 public 方法，不计入函数式接口的抽象方法；接口中只有 void handle(String s) 这一个不是类 Object 成员的抽象方法，满足“有且只有一个抽象方法”的条件，故 FuncInterface2 是函数式接口。', 2, 'lambda 表达式语法', 377, 36),
(592, 192, '9、 下面一个接口定义是否函数式接口？为什么？\n```java\ninterface FuncInterface3{\n      void finalize();\n      void handle(String s);\n}\n```', '不是函数式接口。按教材对接口 Func 的分析，类 Object 的成员方法 clone()是 protected 方法而不是 public 方法，因此不属于被排除的“Object 的 public 方法”；同理 finalize()在类 Object 中也是 protected 方法，所以 void finalize()要计为接口自己声明的 public 抽象方法。FuncInterface3 中同时有 void finalize()和 void handle(String s)两个 public 抽象方法，不满足函数式接口“有且只有一个抽象方法”的条件。', 2, 'lambda 表达式语法', 378, 37),
(593, 192, '10、请简要描述 lambda 表达式的省略规则。', '（1）参数列表中参数的数据类型可以省略，而且必须同时省略，不允许省略其中一部分参数的数据类型而另一部分不省略。（2）在省略参数的数据类型之后，只有参数列表只有一个参数时圆括号才可以省略，其他情况不能省略：参数列表为空时必须保留一对圆括号，参数个数不少于 2 个时圆括号也不能省略。（3）方法体中的语句只有一条时，可以省略花括号和分号；进一步，当这一条语句是 return 语句时，return 也必须省略。', 2, 'lambda 表达式语法', 378, 38),
(594, 192, '11、请简要描述 Java 编译器处理 lambda 表达式的过程。', 'Java 编译器在解析一个 lambda 表达式时，等同于是从一个匿名内部类创建一个匿名对象，通常有三个步骤：①确定 lambda 表达式的数据类型，即由赋值目标或方法形参的接口类型推断出它是实现某个函数式接口的匿名对象；②确定参数的数据类型，由该函数式接口抽象方法的参数列表推断；③确定语句，基于箭头->后的语句确定重写抽象方法的方法体。', 2, 'lambda 表达式语法', 378, 39),
(595, 192, '12、请说明当 lambda 表达式访问外围方法或类中的变量时，有什么限制？', '只能引用外部变量的值而不能改变外部变量的值；并且如果在 lambda 表达式中引用了一个外部变量，这个外部变量也不能在外部改变。也就是说，lambda 表达式访问外围作用域的变量必须是最终变量（即常量）或事实最终（effective final）变量。同时 lambda 表达式的体与嵌套块具有相同的作用域，在 lambda 表达式中声明一个与外部作用域同名的局部变量是不合法的。', 2, 'lambda 表达式作用域', 378, 40),
(596, 192, '1、 给出下面程序的输出结果。\n```java\npublic class Analyze8_1 {\n      private String s = "Test";\n      public static void main(String[] args) {\n            Analyze8_1 obj = new Analyze8_1();\n            Analyze8_1.InnerCls innerObj = obj.new InnerCls();\n            System.out.println(innerObj);\n            System.out.println(obj);\n      }\n      public String toString() {\n            return s + ":" + Analyze8_1.this.s;\n      }\n      class InnerCls{\n            private String s = "内部类";\n            public String toString() {\n                  return s + ":" + Analyze8_1.this.s;\n            }\n      }\n}\n```', '内部类:Test\nTest:Test\n（说明：成员内部类 InnerCls 的 toString 中 s 是被隐藏的自身成员“内部类”，Analyze8_1.this.s 显式引用外嵌类的私有成员“Test”；外嵌类的 toString 中两处 s 都是外嵌类的成员变量，故输出 Test:Test。）', 2, '成员内部类', 378, 41),
(597, 192, '2、 给出下面程序的输出结果。\n```java\npublic class Analyze8_2 {\n      private String s1 = "Test";\n      public static void main(String[] args) {\n            String s1 = "局部内部类";\n            class InnerCls{\n                  private String s = "内部类";\n                  public String toString() {\n                        return s + ":" + s1 ;\n                  }\n            }\n            var innerObj = new InnerCls();\n            var obj = new Analyze8_2();\n            System.out.println(innerObj);\n            System.out.println(obj);\n      }\n      public String toString() {\n            return s1 + ":" + Analyze8_2.this.s1;\n      }\n}\n```', '内部类:局部内部类\nTest:Test\n（说明：InnerCls 是定义在静态方法 main 中的局部内部类，其 toString 中的 s1 引用 main 里定义的局部变量 s1（“局部内部类”），局部内部类不能访问外嵌类的实例成员 s1；外嵌类对象的 toString 中两处 s1 都是实例成员，故输出 Test:Test。）', 2, '局部内部类', 378, 42),
(598, 192, '3、 给出下面程序的输出结果。\n```java\npublic class Analyze8_3 {\n      public static void show(Printer info, String s) {\n            info.print(s + ":" + s);\n      }\n      public static void main(String[] args) {\n            String s1 = "Hello";\n            show(new Printer(){\n                  public void print(String str) {\n                        System.out.println(str + ";" + str);\n                  }\n            }, s1);\n      }\n}\ninterface Printer{\n      void print(String str);\n}\n```', 'Hello:Hello;Hello:Hello\n（说明：show 先把实参拼成 s+“:”+s 即“Hello:Hello”传给匿名内部类对象，匿名内部类重写的 print 再输出 str+“;”+str。）', 2, '匿名内部类', 379, 43),
(599, 192, '4、 给出下面程序的输出结果。\n```java\npublic class Analyze8_4 {\n      public static void show(Printer info, String s) {\n            info.print(s + ":" + s);\n      }\n      public static void main(String[] args) {\n            String s1 = "Java";\n            show(e -> System.out.println(e + ";" + e), s1);\n      }\n}\ninterface Printer1{\n      void print(String str);\n}\n```', 'Java:Java;Java:Java\n（说明：lambda 表达式 e -> System.out.println(e + ";" + e) 替代匿名内部类实现函数式接口，形参 e 得到 show 传入的“Java:Java”，print 内再拼接两次。注意题面把接口名写成 Printer1，而 show 的形参类型是 Printer，需将两者名称统一后才能编译。）', 2, 'lambda 表达式语法', 379, 44),
(600, 192, '5、 给出下面程序的输出结果。\n```java\npublic class Analyze8_5 {\n      public static void main(String[] args) {\n            String[] colors = {"White", "Black", "Yellow", "Green"};\n            ArrayList<String> colorList = new ArrayList<>(Arrays.asList(colors));\n            colorList.forEach(e -> System.out.print( "|" + e + ";"));\n      }\n}\n```', '|White;|Black;|Yellow;|Green;\n（说明：forEach 按列表的迭代顺序对每个元素执行 System.out.print("|" + e + ";")，用 print 不换行，因此四项连成一串输出。）', 2, 'lambda 表达式与 ArrayList', 379, 45),
(601, 192, '6、 给出下面程序的输出结果。\n```java\npublic class Analyze8_6 {\n      public static void main(String[] args) {\n            String[] colors = {"White", "white", "Yellow", "Green"};\n            ArrayList<String> colorList = new ArrayList<>(Arrays.asList(colors));\n            colorList.removeIf(e -> e.equals("White"));\n            colorList.forEach(e -> System.out.print( "|" + e + ";"));\n      }\n}\n```', '|white;|Yellow;|Green;\n（说明：removeIf(e -> e.equals("White")) 的谓词区分大小写，只删除“White”，保留“white”、“Yellow”、“Green”，再由 forEach 按原顺序输出。）', 2, 'lambda 表达式与 ArrayList', 380, 46),
(602, 192, '7、 给出下面程序的输出结果。\n```java\npublic class Analyze8_7 {\n      public static void main(String[] args) {\n            String[] colors = {"White", "Black", "Yellow", "Green"};\n            ArrayList<String> colorList = new ArrayList<>(Arrays.asList(colors));\n            Collections.sort(colorList);\n            colorList.forEach(e -> System.out.print( "|" + e + ";"));\n      }\n}\n```', '|Black;|Green;|White;|Yellow;\n（说明：Collections.sort(colorList) 按 String 的自然顺序（compareTo，大写字母的 Unicode 值小）升序排列后输出。）', 2, 'Comparator 接口', 380, 47),
(603, 192, '8、 给出下面程序的输出结果。\n```java\npublic class Analyze8_8 {\n      public static void main(String[] args) {\n            String[] colors = {"White", "Black", "Yellow", "Green"};\n            ArrayList<String> colorList = new ArrayList<>(Arrays.asList(colors));\n            Collections.sort(colorList, (s1,s2) ->{\n                  if(s1.compareTo(s2) < 0) return 1;\n                  else if(s1.compareTo(s2) == 0) return 0;\n                  else return -1;\n            });\n            colorList.forEach(e -> System.out.print( "|" + e + ";"));\n      }\n}\n```', '|Yellow;|White;|Green;|Black;\n（说明：比较器把 s1.compareTo(s2) < 0 时返回 1、> 0 时返回 -1，即与自然顺序相反，得到降序排列的结果。）', 2, 'Comparator 接口', 380, 48),
(604, 192, '1、 一个桌椅组合商品，由一个桌子和一个椅子构成，桌子有两种样式，椅子有四种样式。请定义一个桌椅组合商品类 SuitDesk$Chair，在该类内部有两个成员内部类：桌子类 Desk、椅子类 Chair。\n桌椅组合商品类 SuitDesk$Chair 具有私有 String 属性 color、deskStyle、chairStyle，具有私有 Desk 对象、Chair 对象；提供一个具有三个参数（color、deskStyle、chairStyle）的构造方法，在该构造方法中，调用 Desk 类和 Chair 类的无参构造方法分别初始化 Desk 对象和 Chair 对象；提供三个成员变量（color、deskStyle、chairStyle）的 get 方法和 set 方法；对 toString 方法进行重写，重写方法体的代码如下：\n```java\nreturn "桌子组合商品颜色：" + color + "\\n" + desk.toString() + "\\n" + chair.toString();\n```\nDesk 类具有私有 String 属性 style(值为：豪华型、普通型)，提供成员变量 style 的 get 方法和 set 方法；提供一个无参构造方法，使用外嵌类的成员变量 deskStyle 初始化 style 的值；对 toString 方法进行重写，重写方法体的代码如下：\n```java\nreturn "桌子样式：" + style;\n```\nChair 类具有 String 属性 style（值为：靠背高豪华型、靠背低豪华型、靠背高普通型、靠背低普通型）。提供成员变量 style 的 get 方法和 set 方法；提供一个无参构造方法，使用外嵌类的成员变量 chairStyle 初始化 style 的值；对 toString 方法进行重写，重写方法体的代码如下：\n```java\nreturn "椅子样式：" + style;\n```\n请实现桌椅组合商品类 SuitDesk$Chair，并使用成员内部类实现类 Desk 和类 Chair，再编写一个测试类，提示用户输入桌椅组合商品的选择，创建一个桌椅组合商品类对象，最后输出所选择的商品信息。一个运行示例如下所示。\n```\n请输入桌椅组合商品选择,输入数字：\n颜色选择:1.RED 2.BLUE 3. BROWN\n1\n桌子选择：1.豪华型 2.普通型\n2\n椅子选择：1.靠背高豪华型 2.靠背高普通型 3.靠背低豪华型 4.靠背低普通型\n3\n桌子组合商品颜色：RED\n桌子样式：豪华型\n椅子样式：靠背高豪华型\n```', '参考代码：\n（1）商品类 SuitDesk$Chair.java\n```java\npublic class SuitDesk$Chair {\n    private String color, deskStyle, chairStyle;\n    private Desk desk; private Chair chair;\n    public SuitDesk$Chair(String color, String deskStyle, String chairStyle) {\n        this.color = color; this.deskStyle = deskStyle; this.chairStyle = chairStyle;\n        desk = new Desk(); chair = new Chair();\n    }\n    public String getColor() { return color; } public void setColor(String c) { color = c; }\n    public String getDeskStyle() { return deskStyle; } public void setDeskStyle(String s) { deskStyle = s; }\n    public String getChairStyle() { return chairStyle; } public void setChairStyle(String s) { chairStyle = s; }\n    public String toString() { return "桌子组合商品颜色：" + color + "\\n" + desk.toString() + "\\n" + chair.toString(); }\n    class Desk { //成员内部类\n        private String style;\n        public Desk() { style = deskStyle; } //使用外嵌类的成员变量初始化\n        public String getStyle() { return style; } public void setStyle(String s) { style = s; }\n        public String toString() { return "桌子样式：" + style; }\n    }\n    class Chair { //成员内部类\n        String style;\n        public Chair() { style = chairStyle; }\n        public String getStyle() { return style; } public void setStyle(String s) { style = s; }\n        public String toString() { return "椅子样式：" + style; }\n    }\n}\n```\n（2）测试类\n```java\nimport java.util.Scanner;\npublic class SuitDesk$ChairTest {\n    public static void main(String[] args) {\n        Scanner input = new Scanner(System.in);\n        String[] colors = {"RED", "BLUE", "BROWN"};\n        String[] deskStyles = {"豪华型", "普通型"};\n        String[] chairStyles = {"靠背高豪华型", "靠背高普通型", "靠背低豪华型", "靠背低普通型"};\n        System.out.println("请输入桌椅组合商品选择,输入数字：");\n        System.out.println("颜色选择:1.RED 2.BLUE 3. BROWN");\n        String color = colors[input.nextInt() - 1];\n        System.out.println("桌子选择：1.豪华型 2.普通型");\n        String deskStyle = deskStyles[input.nextInt() - 1];\n        System.out.println("椅子选择：1.靠背高豪华型 2.靠背高普通型 3.靠背低豪华型 4.靠背低普通型");\n        String chairStyle = chairStyles[input.nextInt() - 1];\n        System.out.println(new SuitDesk$Chair(color, deskStyle, chairStyle));\n    }\n}\n```\n注意：题面运行示例中桌子输入 2、椅子输入 3，却输出“豪华型”“靠背高豪华型”，与选项列表不对应；按本代码选项编号与输入数字一致，输入 1、1、1 即得到示例所示输出。', 2, '成员内部类', 380, 49),
(605, 192, '2、 编写一个程序模拟对一个局域网中计算机节点的管理，首先定义一个节点管理类 NodeManager，然后在节点管理类内部定义一个成员内部类——节点类 Node。\n(1)节点管理类，其数据域包括：Node 数组 nodes、当前在线节点数 curNodes。为这些数据域提供相应的 get 方法和 set 方法。定义一个无参构造方法，以及一个带参数（Node 数组、当前在线节点数）构造方法。重写 toString 方法，显示当前在线节点数和节点信息，其代码如下：\n```java\nString strNodes = "";\nfor(Node node: nodes) {\n      strNodes += node.toString() + "\\n";\n}\nreturn "NodeManager:当前节点数" + curNodes +"\\n"\n + strNodes;\n```\n(2)节点类的数据域包括：id(String 类型)、url(String 类型)、登录时间 loginTime（Date 类型）。为这些数据域提供 get 方法和 set 方法。提供一个无参构造方法、一个带两个参数（id、url）的构造方法、以及一个带全部参数的构造方法。重写 toString 方法，显示当前在线节点数和节点信息，其代码如下：return "Node:"+ id + ",url:" + url;\n编写一个测试类，创建一个 NodeManager 对象，管理三个节点对象，三个节点对象信息如下：(1)节点 1：id=“2023001”，url = “192.168.10.100”；(2)节点 2：id=“2023002”，url = “192.168.10.101”；(3)节点 3：id=“2023003”，url = “192.168.10.102”。然后，输出 NodeManager 对象的信息。运行结果示例如下：\n```\nNodeManager:当前节点数 3\nNode:2023001,url:192.168.10.100\nNode:2023002,url:192.168.10.101\nNode:2023003,url:192.168.10.102\n```', '参考代码：\n（1）节点管理类与成员内部类节点类\n```java\nimport java.util.Date;\npublic class NodeManager {\n    private Node[] nodes; private int curNodes;\n    public NodeManager() { }\n    public NodeManager(Node[] nodes, int curNodes) { this.nodes = nodes; this.curNodes = curNodes; }\n    public Node[] getNodes() { return nodes; }\n    public void setNodes(Node[] nodes) { this.nodes = nodes; }\n    public int getCurNodes() { return curNodes; }\n    public void setCurNodes(int curNodes) { this.curNodes = curNodes; }\n    public String toString() {\n        String strNodes = "";\n        for (Node node : nodes) { strNodes += node.toString() + "\\n"; }\n        return "NodeManager:当前节点数" + curNodes + "\\n" + strNodes;\n    }\n    class Node { //成员内部类\n        private String id, url; private Date loginTime;\n        public Node() { }\n        public Node(String id, String url) { this.id = id; this.url = url; this.loginTime = new Date(); }\n        public Node(String id, String url, Date loginTime) { this.id = id; this.url = url; this.loginTime = loginTime; }\n        public String getId() { return id; } public void setId(String id) { this.id = id; }\n        public String getUrl() { return url; } public void setUrl(String url) { this.url = url; }\n        public Date getLoginTime() { return loginTime; } public void setLoginTime(Date t) { loginTime = t; }\n        public String toString() { return "Node:" + id + ",url:" + url; }\n    }\n}\n```\n（2）测试类\n```java\npublic class NodeManagerTest {\n    public static void main(String[] args) {\n        NodeManager nm = new NodeManager();\n        NodeManager.Node[] nodes = new NodeManager.Node[3];\n        nodes[0] = nm.new Node("2023001", "192.168.10.100");\n        nodes[1] = nm.new Node("2023002", "192.168.10.101");\n        nodes[2] = nm.new Node("2023003", "192.168.10.102");\n        nm.setNodes(nodes); nm.setCurNodes(3);\n        System.out.println(nm);\n    }\n}\n```\n成员内部类对象的创建必须先有外嵌类实例，写成 nm.new Node(...)，即“外嵌类实例名.new 内部类类名(参数列表)”。', 2, '成员内部类', 381, 50),
(606, 192, '3、 声明一个函数式接口 StringNumberHandler，提供一个处理字符串数字的抽象方法：Number handle(String str_num);\n编写一个静态方法 printNumber()，如下所示：\n```java\npublic static void printNumber(StringNumberHandler num, String s) {\n            num.handle(s);\n}\n```\n然后，在 main 方法中提示用户输入一个数字字符串，基于输入的数字字符串，程序完成如下功能：\n(1) 功能 1：取数字字符串的整数部分，输出取整后的整数值。\n(2) 功能 2：按四舍五入保留小数点后两位，输出保留两位小数的浮点值。\n基于上述说明，要求按以下四种不同形式完成四个独立的程序：\n(1) 请使用两个成员内部类 IntegerHandler、DoubleHandler 实现函数式接口，分别完成上面的两个功能。\n(2) 请使用两个成员局部内部实现函数式接口，分别完成上面两个功能。\n(3) 请使用两个匿名内部类实现函数式接口，分别完成上面两个功能。\n(4) 请使用 lambda 表达式，分别完成上面两个功能。\n最后，输出结果。一个运行示例如下所示：\n```\n请输入一个实数数字串:12363.456723\nNumber:12363\nNumber:12363.46\n```', '参考代码：\n接口与静态方法（四种形式共用）\n```java\nimport java.util.Scanner;\n@FunctionalInterface\ninterface StringNumberHandler {\n    Number handle(String str_num);\n}\npublic class NumberHandlerDemo {\n    public static void printNumber(StringNumberHandler num, String s) {\n        num.handle(s);\n    }\n}\n```\n（1）两个成员内部类实现接口\n```java\nclass IntegerHandler implements StringNumberHandler {\n    public Number handle(String str_num) {\n        int v = (int) Double.parseDouble(str_num);\n        System.out.println("Number:" + v); return v;\n    }\n}\nclass DoubleHandler implements StringNumberHandler {\n    public Number handle(String str_num) {\n        System.out.printf("Number:%.2f\\n", Double.parseDouble(str_num));\n        return Double.parseDouble(str_num);\n    }\n}\n// main 中：\nString s = input.next();\nNumberHandlerDemo.printNumber(new IntegerHandler(), s);\nNumberHandlerDemo.printNumber(new DoubleHandler(), s);\n```\n（2）两个局部内部类实现接口（定义在 main 内部）\n```java\npublic static void main(String[] args) {\n    Scanner input = new Scanner(System.in);\n    System.out.print("请输入一个实数数字串:");\n    String s = input.next();\n    class LocalIntHandler implements StringNumberHandler {\n        public Number handle(String n) {\n            int v = (int) Double.parseDouble(n);\n            System.out.println("Number:" + v); return v;\n        }\n    }\n    class LocalDblHandler implements StringNumberHandler {\n        public Number handle(String n) {\n            System.out.printf("Number:%.2f\\n", Double.parseDouble(n));\n            return Double.parseDouble(n);\n        }\n    }\n    printNumber(new LocalIntHandler(), s);\n    printNumber(new LocalDblHandler(), s);\n}\n```\n（3）两个匿名内部类实现接口\n```java\nprintNumber(new StringNumberHandler() {\n    public Number handle(String n) {\n        int v = (int) Double.parseDouble(n);\n        System.out.println("Number:" + v); return v;\n    }\n}, s);\nprintNumber(new StringNumberHandler() {\n    public Number handle(String n) {\n        System.out.printf("Number:%.2f\\n", Double.parseDouble(n));\n        return Double.parseDouble(n);\n    }\n}, s);\n```\n（4）lambda 表达式\n```java\nprintNumber(n -> { int v = (int) Double.parseDouble(n);\n    System.out.println("Number:" + v); return v; }, s);\nprintNumber(n -> { System.out.printf("Number:%.2f\\n", Double.parseDouble(n));\n    return Double.parseDouble(n); }, s);\n```\n输入 12363.456723 时，四种形式都输出 Number:12363 与 Number:12363.46（printf 的 %.2f 按四舍五入保留两位小数）。', 2, 'lambda 表达式语法', 382, 51),
(607, 192, '4、 设计一个函数式接口 FilterNumber，它有一个抽象方法：public abstact Number[] handle(Number[] nums)。应用 lambda 表达式完成：\n(1)给定一个 Integer 数组，将该整数数组中的奇数过滤掉，保留偶数，并输出结果。\n(2)给定一个 Double 型数组，将该浮点型数组中小于 60 的值去掉，并输出结果。\n在测试类中设计一个静态方法 filterNums()，如下所示：\n```java\npublic static Number[] filterNums(FilterNumber f, Number[] nums) {\n      return f.handle(nums);\n}\n```\n在测试类中，假定一个整数数组具有初值：2, 3, 5, 6, 8, 10, 13, 18；一个 Double 型数组具有初值：75.6, 65.5, 54.5, 59.5, 86.6, 79.3, 35.5，则运行结果如下所示：\n```\n过滤奇数后，数组中的偶数是： 2 6 8 10 18\n过滤掉小于 60 的数后，数组中的数是： 75.6 65.5 86.6 79.3\n```', '参考代码：\n（1）过滤整数数组中的奇数\n```java\nimport java.util.ArrayList; import java.util.List;\nimport java.util.function.Predicate;\n@FunctionalInterface\ninterface FilterNumber {\n    public abstract Number[] handle(Number[] nums);\n}\npublic class FilterNumberDemo {\n    public static Number[] filterNums(FilterNumber f, Number[] nums) {\n        return f.handle(nums);\n    }\n    static Number[] keep(Number[] src, Predicate<Number> p) {\n        List<Number> t = new ArrayList<>();\n        for (Number n : src) if (p.test(n)) t.add(n);\n        return t.toArray(new Number[0]);\n    }\n    public static void main(String[] args) {\n        Integer[] ints = {2, 3, 5, 6, 8, 10, 13, 18};\n        Double[] dbs = {75.6, 65.5, 54.5, 59.5, 86.6, 79.3, 35.5};\n        System.out.print("过滤奇数后，数组中的偶数是： ");\n        for (Number n : filterNums(nums -> keep(nums, m -> m.intValue() % 2 == 0), ints))\n            System.out.print(n + " ");\n```\n（2）过滤浮点型数组中小于 60 的值\n```java\n        System.out.print("\\n过滤掉小于 60 的数后，数组中的数是： ");\n        for (Number n : filterNums(nums -> keep(nums, m -> m.doubleValue() >= 60), dbs))\n            System.out.print(n + " ");\n    }\n}\n```\nInteger[]、Double[] 是 Number[] 的子类型数组，可作为实参传入；运行输出为“2 6 8 10 18”和“75.6 65.5 86.6 79.3”。', 2, 'lambda 表达式语法', 382, 52),
(608, 192, '5、 使用 ArrayList 的 removeIf()方法过滤一个整数序列的偶数，并使用 ArrayList 的 forEach()方法输出过滤后的结果，整数之间采用空格分隔。假定一个整数序列是 2, 3, 5, 6, 8, 10, 13, 18，那么运行结果如下所示：\n```\n整数序列过滤掉偶数后：3 5 13\n```', '参考代码：\n```java\nimport java.util.ArrayList;\nimport java.util.Arrays;\npublic class RemoveEvenDemo {\n    public static void main(String[] args) {\n        Integer[] sequence = {2, 3, 5, 6, 8, 10, 13, 18};\n        ArrayList<Integer> list = new ArrayList<>(Arrays.asList(sequence));\n        list.removeIf(e -> e % 2 == 0); //谓词为真即删除，删除偶数\n        System.out.print("整数序列过滤掉偶数后：");\n        list.forEach(e -> System.out.print(e + " "));\n    }\n}\n```\n运行结果：整数序列过滤掉偶数后：3 5 13 （末尾还有一个空格）。', 2, 'lambda 表达式与 ArrayList', 382, 53),
(609, 192, '6、 使用 ArrayList 的 removeIf()方法过滤一个成绩单中低于 60 分的序列，然后使用 ArrayList 的 forEach()方法输出过滤后的结果，整数之间采用空格分隔。假定一个成绩单中的成绩是：75, 63, 85, 46, 48, 90, 53, 78，那么运行结果如下：\n```\n成绩不低于 60 的有：75 63 85 90 78\n```', '参考代码：\n```java\nimport java.util.ArrayList;\nimport java.util.Arrays;\npublic class RemoveLowScoreDemo {\n    public static void main(String[] args) {\n        Integer[] scores = {75, 63, 85, 46, 48, 90, 53, 78};\n        ArrayList<Integer> list = new ArrayList<>(Arrays.asList(scores));\n        list.removeIf(e -> e < 60); //删除低于 60 分的成绩\n        System.out.print("成绩不低于 60 的有：");\n        list.forEach(e -> System.out.print(e + " "));\n    }\n}\n```\n运行结果：成绩不低于 60 的有：75 63 85 90 78 （末尾还有一个空格）。', 2, 'lambda 表达式与 ArrayList', 382, 54),
(610, 192, '7、 编写一个学生类，它的数据域有：学号 stuID(String 类型)、姓名（String 类型）、语文成绩 ChineseScore（int 类型，0-100）、数学成绩 MathScore（int 类型，0-100）、英语成绩 EnglishScore（int 类型，0-100），这些数据域均为私有的，并为这些数据域设计相应的 get 方法和 set 方法。提供一个无参构造方法，一个有两个参数（stuID）的构造方法，一个带所有参数的构造方法。提供一个 toString 方法，输出学生信息，代码如下：\n```java\nreturn "学号=" + stuID + ", 姓名=" + name + "\\n 语文成绩=" + ChineseScore + ", 数学成绩=" + MathScore + ", 英语成绩=" + EnglishScore;\n```\n编写一个测试类，创建一个学生类对象数组 students 具有 5 个学生对象，这 5 个学生对象信息如下表所示：\n| 学号 | 姓名 | 语文成绩 | 数学成绩 | 英语成绩 |\n| --- | --- | --- | --- | --- |\n| 20230001 | 张三 | 65 | 75 | 85 |\n| 20230002 | 李四 | 90 | 98 | 70 |\n| 20230003 | 王五 | 75 | 85 | 80 |\n| 20230004 | 赵六 | 80 | 82 | 90 |\n| 20230005 | 孙七 | 85 | 95 | 95 |\n然后，进一步设计一个函数式接口 FilterScore，它有一个抽象方法：\n```java\npublic abstract Student[] handle(Student[] stus);\n```\n在测试类中编写一个静态方法 FilterStudent：\n```java\npublic static Student[] filterStudent(FilterScore f, Student[] stus) {\n   return f.handle(stus);\n}\n```\n在测试类中，应用 lambda 表达式，分别过滤语文成绩、数学成绩、英语成绩不低于 80 的学生名单，并输出结果信息。运行结果如下所示\n```\n语文成绩不低于 80 分的学生：\n学号：20230002，姓名：李四,语文成绩：90\n学号：20230004，姓名：赵六,语文成绩：80\n学号：20230005，姓名：孙七,语文成绩：85\n数学成绩不低于 80 分的学生：\n学号：20230002，姓名：李四,数学成绩：98\n学号：20230003，姓名：王五,数学成绩：85\n学号：20230004，姓名：赵六,数学成绩：82\n学号：20230005，姓名：孙七,数学成绩：95\n英语成绩不低于 80 分的学生：\n学号：20230001，姓名：张三,英语成绩：85\n学号：20230003，姓名：王五,英语成绩：80\n学号：20230004，姓名：赵六,英语成绩：90\n学号：20230005，姓名：孙七,英语成绩：95\n```', '参考代码：\n（1）学生类 Student.java（第 8~11 题共用）\n```java\npublic class Student {\n    private String stuID, name;\n    private int ChineseScore, MathScore, EnglishScore;\n    public Student() { }\n    public Student(String stuID) { this.stuID = stuID; }\n    public Student(String stuID, String name, int cs, int ms, int es) {\n        this.stuID = stuID; this.name = name;\n        ChineseScore = cs; MathScore = ms; EnglishScore = es;\n    }\n    public String getStuID() { return stuID; } public void setStuID(String s) { stuID = s; }\n    public String getName() { return name; } public void setName(String n) { name = n; }\n    public int getChineseScore() { return ChineseScore; } public void setChineseScore(int s) { ChineseScore = s; }\n    public int getMathScore() { return MathScore; } public void setMathScore(int s) { MathScore = s; }\n    public int getEnglishScore() { return EnglishScore; } public void setEnglishScore(int s) { EnglishScore = s; }\n    public String toString() {\n        return "学号=" + stuID + ", 姓名=" + name + "\\n 语文成绩=" + ChineseScore\n            + ", 数学成绩=" + MathScore + ", 英语成绩=" + EnglishScore;\n    }\n}\n```\n（2）函数式接口与测试类\n```java\nimport java.util.ArrayList; import java.util.List;\nimport java.util.function.Predicate;\n@FunctionalInterface\ninterface FilterScore { public abstract Student[] handle(Student[] stus); }\npublic class StudentFilterTest {\n    public static Student[] filterStudent(FilterScore f, Student[] stus) { return f.handle(stus); }\n    static Student[] sel(Student[] stus, Predicate<Student> p) {\n        List<Student> t = new ArrayList<>();\n        for (Student s : stus) if (p.test(s)) t.add(s);\n        return t.toArray(new Student[0]); }\n    public static void main(String[] args) {\n        Student[] students = { new Student("20230001", "张三", 65, 75, 85),\n            new Student("20230002", "李四", 90, 98, 70), new Student("20230003", "王五", 75, 85, 80),\n            new Student("20230004", "赵六", 80, 82, 90), new Student("20230005", "孙七", 85, 95, 95) };\n        System.out.println("语文成绩不低于 80 分的学生：");\n        for (Student s : filterStudent(st -> sel(st, x -> x.getChineseScore() >= 80), students))\n            System.out.println("学号：" + s.getStuID() + "，姓名：" + s.getName() + ",语文成绩：" + s.getChineseScore());\n        System.out.println("数学成绩不低于 80 分的学生：");\n        for (Student s : filterStudent(st -> sel(st, x -> x.getMathScore() >= 80), students))\n            System.out.println("学号：" + s.getStuID() + "，姓名：" + s.getName() + ",数学成绩：" + s.getMathScore());\n        System.out.println("英语成绩不低于 80 分的学生：");\n        for (Student s : filterStudent(st -> sel(st, x -> x.getEnglishScore() >= 80), students))\n            System.out.println("学号：" + s.getStuID() + "，姓名：" + s.getName() + ",英语成绩：" + s.getEnglishScore());\n    }\n}\n```\n输出与题面示例一致：语文 20230002/20230004/20230005，数学 20230002/20230003/20230004/20230005，英语 20230001/20230003/20230004/20230005。', 2, 'lambda 表达式语法', 382, 55),
(611, 192, '8、 基于第 7 题编写的学生类，编写一个测试类，用 ArrayList 存储学生对象（可用第 5 题的测试数据），然后按照语文成绩(升序)、数学成绩(降序)、英语成绩（降序）进行排序，排序使用 Collections 类的方法 sort()，并应用 ArrayList 的 forEach()方法输出排序后的结果。运行结果如下所示：\n```\n语文成绩 -> 学生姓名\n65     -> 张三\n75     -> 王五\n80     -> 赵六\n85     -> 孙七\n90     -> 李四\n```', '参考代码：\n```java\nimport java.util.ArrayList; import java.util.Arrays; import java.util.Collections;\npublic class StudentSortTest8 {\n    public static void main(String[] args) {\n        ArrayList<Student> list = new ArrayList<>(Arrays.asList(\n            new Student("20230001", "张三", 65, 75, 85), new Student("20230002", "李四", 90, 98, 70),\n            new Student("20230003", "王五", 75, 85, 80), new Student("20230004", "赵六", 80, 82, 90),\n            new Student("20230005", "孙七", 85, 95, 95)));\n        System.out.println("语文成绩 -> 学生姓名");\n        Collections.sort(list, (s1, s2) -> s1.getChineseScore() - s2.getChineseScore()); //升序\n        list.forEach(s -> System.out.println(s.getChineseScore() + "     -> " + s.getName()));\n        System.out.println("数学成绩 -> 学生姓名");\n        Collections.sort(list, (s1, s2) -> s2.getMathScore() - s1.getMathScore()); //降序\n        list.forEach(s -> System.out.println(s.getMathScore() + "     -> " + s.getName()));\n        System.out.println("英语成绩 -> 学生姓名");\n        Collections.sort(list, (s1, s2) -> s2.getEnglishScore() - s1.getEnglishScore()); //降序\n        list.forEach(s -> System.out.println(s.getEnglishScore() + "     -> " + s.getName()));\n    }\n}\n```\n语文成绩升序输出 65 张三、75 王五、80 赵六、85 孙七、90 李四，与题面示例一致；题中“第 5 题的测试数据”应为第 7 题的学生数据。若要一次排序同时按三个优先级比较，把比较器写成 s1.getChineseScore() - s2.getChineseScore() 为 0 时再依次比较数学、英语成绩的降序即可。', 2, 'Comparator 接口', 383, 56),
(612, 192, '9、 基于第 7 题编写的学生类，编写一个测试类，用 ArrayList 存储学生对象（可用第 5 题的测试数据），然后按照数学成绩(降序)、英语成绩（降序）进行两次排序，排序使用 Collections 类的方法 sort()，并应用 ArrayList 的 forEach()方法输出排序后的结果。运行结果如下所示：\n```\n数学成绩 |英语成绩 | -> 学生姓名\n95  |95    | -> 孙七\n82  |90    | -> 赵六\n75  |85    | -> 张三\n85  |80    | -> 王五\n98  |70    | -> 李四\n```', '参考代码：\n```java\nimport java.util.ArrayList; import java.util.Arrays; import java.util.Collections;\npublic class StudentSortTest9 {\n    public static void main(String[] args) {\n        ArrayList<Student> list = new ArrayList<>(Arrays.asList(\n            new Student("20230001", "张三", 65, 75, 85), new Student("20230002", "李四", 90, 98, 70),\n            new Student("20230003", "王五", 75, 85, 80), new Student("20230004", "赵六", 80, 82, 90),\n            new Student("20230005", "孙七", 85, 95, 95)));\n        System.out.println("数学成绩 |英语成绩 | -> 学生姓名");\n        Collections.sort(list, (s1, s2) -> s2.getMathScore() - s1.getMathScore()); //数学降序\n        list.forEach(s -> System.out.println(s.getMathScore() + "  |" + s.getEnglishScore()\n            + "    | -> " + s.getName()));\n        System.out.println("第二次排序：英语成绩降序");\n        Collections.sort(list, (s1, s2) -> s2.getEnglishScore() - s1.getEnglishScore()); //英语降序\n        list.forEach(s -> System.out.println(s.getMathScore() + "  |" + s.getEnglishScore()\n            + "    | -> " + s.getName()));\n    }\n}\n```\n按“数学成绩降序”实际输出为：98|70 李四、95|95 孙七、85|80 王五、82|90 赵六、75|85 张三；英语降序为 95 孙七、90 赵六、85 张三、80 王五、70 李四。题面给出的示例输出既不是数学降序也不是英语降序，与题目要求不符。', 2, 'Comparator 接口', 383, 57),
(613, 192, '10、基于第 7 题编写的学生类，在学生类中增加一个计算总分的方法 getTotalScore，编写一个测试类，用 ArrayList 存储学生对象（可用第 5 题的测试数据），并按照总分(升序)进行排序，排序使用 Collections 类的方法 sort()，最后使用 ArrayList 的 forEach()方法输出总分及相应学生信息，运行结果如下所示：\n```\n总分 -> 学生姓名\n225 -> 张三\n240 -> 王五\n252 -> 赵六\n258 -> 李四\n275 -> 孙七\n```', '参考代码：\n（1）在学生类中增加计算总分的方法\n```java\npublic int getTotalScore() { return ChineseScore + MathScore + EnglishScore; }\n```\n（2）测试类\n```java\nimport java.util.ArrayList; import java.util.Arrays; import java.util.Collections;\npublic class StudentTotalSortTest {\n    public static void main(String[] args) {\n        ArrayList<Student> list = new ArrayList<>(Arrays.asList(\n            new Student("20230001", "张三", 65, 75, 85), new Student("20230002", "李四", 90, 98, 70),\n            new Student("20230003", "王五", 75, 85, 80), new Student("20230004", "赵六", 80, 82, 90),\n            new Student("20230005", "孙七", 85, 95, 95)));\n        Collections.sort(list, (s1, s2) -> s1.getTotalScore() - s2.getTotalScore()); //总分升序\n        System.out.println("总分 -> 学生姓名");\n        list.forEach(s -> System.out.println(s.getTotalScore() + " -> " + s.getName()\n            + "（" + s.getStuID() + "）"));\n    }\n}\n```\n运行结果：225 -> 张三、240 -> 王五、252 -> 赵六、258 -> 李四、275 -> 孙七，与题面示例一致。', 2, 'Comparator 接口', 384, 58),
(614, 192, '11、基于第 7 题编写的学生类，编写一个测试类，用 ArrayList 存储学生对象（可用第 5 题的测试数据），然后用 ArrayList 的方法 removeIf()，过滤掉语文成绩低于 80、数学成绩低于 80、英语成绩低于 80 分的学生对象，并按照数学成绩(升序)进行排序，排序使用 Collections 类的方法 sort()，最后使用 ArrayList 的 forEach()方法输出语文、英语、数学三科都不低于 80 分的学生对象。运行结果如下所示：\n```\n学号=20230004, 姓名=赵六\n语文成绩=80, 数学成绩=82, 英语成绩=90\n学号=20230005, 姓名=孙七\n语文成绩=85, 数学成绩=95, 英语成绩=95\n```', '参考代码：\n```java\nimport java.util.ArrayList; import java.util.Arrays; import java.util.Collections;\npublic class StudentRemoveIfTest {\n    public static void main(String[] args) {\n        ArrayList<Student> list = new ArrayList<>(Arrays.asList(\n            new Student("20230001", "张三", 65, 75, 85), new Student("20230002", "李四", 90, 98, 70),\n            new Student("20230003", "王五", 75, 85, 80), new Student("20230004", "赵六", 80, 82, 90),\n            new Student("20230005", "孙七", 85, 95, 95)));\n        list.removeIf(s -> s.getChineseScore() < 80 || s.getMathScore() < 80 || s.getEnglishScore() < 80);\n        Collections.sort(list, (s1, s2) -> s1.getMathScore() - s2.getMathScore()); //数学成绩升序\n        list.forEach(s -> System.out.println("学号=" + s.getStuID() + ", 姓名=" + s.getName()\n            + "\\n语文成绩=" + s.getChineseScore() + ", 数学成绩=" + s.getMathScore()\n            + ", 英语成绩=" + s.getEnglishScore()));\n    }\n}\n```\n三科都不低于 80 分的只有赵六、孙七，按数学成绩升序输出：学号=20230004, 姓名=赵六 / 语文成绩=80, 数学成绩=82, 英语成绩=90；学号=20230005, 姓名=孙七 / 语文成绩=85, 数学成绩=95, 英语成绩=95，与题面示例一致。', 2, 'lambda 表达式与 ArrayList', 384, 59),
(615, 192, '12、在程序清单 8-14 的基础上，请编写程序，使得学生对象按照年龄降序排列，并输出排序后的结果，运行结果如下所示：\n```\n学号  姓名      年龄\n40105 赵三    13\n50103 关一    12\n40103 张二    11\n50109 李四    10\n60103 黄羽    9\n```', '参考代码：\n```java\nimport java.util.ArrayList; import java.util.Arrays; import java.util.Collections;\npublic class AgeDescDemo {\n    public static void main(String[] args) {\n        Pupils[] pArray = { new Pupils("50103", "关一", 12, 1.45), new Pupils("40103", "张二", 11, 1.43),\n            new Pupils("40105", "赵三", 13, 1.63), new Pupils("50109", "李四", 10, 1.35),\n            new Pupils("60103", "黄羽", 9, 1.41) }; //与程序清单 8-14 相同\n        ArrayList<Pupils> list = new ArrayList<>(Arrays.asList(pArray));\n        Collections.sort(list, (o1, o2) -> { //按年龄降序\n            if (o1.age < o2.age) return 1;\n            else if (o1.age == o2.age) return 0;\n            else return -1;\n        });\n        System.out.println("学号  姓名      年龄");\n        list.forEach(e -> System.out.printf("%s %s    %d%n", e.ID, e.name, e.age));\n    }\n}\n```\n亦可把 lambda 表达式写成方法引用：在私有静态内嵌类中定义 static int cmp(Pupils o1, Pupils o2) 实现上述降序比较，再调用 Collections.sort(list, AgeDescComparator::cmp)。运行结果为 40105 赵三 13、50103 关一 12、40103 张二 11、50109 李四 10、60103 黄羽 9，与题面示例一致。', 2, 'Comparator 接口', 384, 60);
